window.PCEC_COURSES = [{"id":"musculoskeletal","title":"근골격계질환 전문간병사","category":"질환군 교육","scope":"경추·척수손상 환자(사지마비 등), 요추 추간판탈출증(허리디스크) 환자, 골관절염·류마티스관절염·골다공증·골절·척추관협착증·근감소·수술 후 재활 환자","tracks":["근골격계"],"units":[{"id":"M-01","name":"골관절염","track":"근골격계","reason":"활동과 휴식은 개인별 계획에 맞춘다. 통증을 참게 하며 강제로 운동시키지 않는다.","scenario":"무릎 통증으로 세면실까지 걷기를 꺼린다.","focus":"통증과 일상 이동 기능","action":"통증·피로에 맞추어 쉬어 가며 처방된 보행 보조를 돕는다.","followup":"활동 후 통증과 이동 거리를 기록한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-02","name":"류마티스관절염","track":"근골격계","reason":"염증성 질환과 퇴행성 질환을 구분해 배우되 진단은 의료진이 한다. 침대 시트를 갈 때도 간병사의 손을 살펴보세요. 일반 시트의 네 귀를 손끝으로 세게 당겨 묶는 작업을 여러 침대에서 반복하면 손가락에 부담이 쌓입니다. 매트리스 규격에 맞는 네 귀 고무줄형 커버가 있으면 묶는 동작을 줄일 수 있습니다. 일반 시트만 있다면 먼저 크기와 놓인 위치를 확인하세요. 천이 모자라면 억지로 당기지 말고 알맞은 시트를 요청하세요. 손가락이 휘어 보이거나 펴기 어려워지면 어떤 작업을 얼마나 반복했는지 알리고 진료를 받으세요.","scenario":"손가락 관절이 뻣뻣해 단추를 잠그기 어렵다.","focus":"관절 기능과 세밀한 동작 제한","action":"여유 시간을 주고 보조 도구·관절 보호 계획을 따른다.","followup":"가능한 자기 돌봄 수준을 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-03","name":"골다공증","track":"근골격계","reason":"골밀도 저하는 골절 위험을 높인다. 겉으로 상처가 없다고 골절을 배제하지 않는다.","scenario":"가벼운 충격 후 새 등 통증을 호소한다.","focus":"취약 골절 가능성과 새 통증","action":"무리한 움직임을 멈추고 통증 상황을 보고한다.","followup":"평가 전후 이동 지시를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-04","name":"고관절 골절 의심","track":"근골격계","reason":"골절 의심 시 걷게 하여 확인하는 행동은 피한다.","scenario":"넘어진 뒤 엉덩이가 아프고 일어서지 못한다.","focus":"낙상 후 체중부하 불가","action":"억지로 일으키지 않고 즉시 도움을 요청한다.","followup":"통증과 구조 인계 내용을 기록한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-05","name":"인공관절 수술 후","track":"근골격계","reason":"수술 접근법과 상태별 주의사항이 달라 모든 환자에게 같은 제한을 적용하지 않는다.","scenario":"수술 환자를 옮길 때 다리를 어떻게 놓을지 모르겠다.","focus":"수술별 자세·체중부하 제한","action":"수술팀·재활팀의 최신 이동 지시를 먼저 확인한다.","followup":"이동 후 통증·어지럼을 살핀다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-06","name":"척추 압박골절","track":"근골격계","reason":"갑작스러운 비틀기나 견인은 피한다. 보조기 사용은 개별 지시를 따른다. 몸에서 먼 곳의 하중을 허리를 굽히거나 비튼 채 당기면 허리 부담이 커집니다. 환자의 척추 보호 계획을 먼저 확인하고, 침대 높이와 작업 위치를 맞춘 다음 정해진 이동 보조기구와 인력을 확보합니다.","scenario":"침상에서 몸을 비틀 때 통증이 커진다.","focus":"척추 안정과 자세 보조","action":"훈련받은 방법으로 지지하고 허용된 움직임을 확인한다.","followup":"피부 압박과 통증 변화를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-07","name":"척추관협착증","track":"근골격계","reason":"기존 증상과 새 근력·배뇨 변화는 구분한다.","scenario":"걷다 다리가 저려 자주 멈춘다.","focus":"보행 관련 증상과 안전","action":"휴식·보행 보조 계획에 맞추어 이동하고 변화를 보고한다.","followup":"증상 발생 거리와 회복 양상을 기록한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-08","name":"급성 신경 압박 징후","track":"근골격계","reason":"만성 요통으로 넘기지 말아야 할 변화다. 마사지나 운동을 먼저 시행하지 않는다.","scenario":"허리 통증에 새 다리 마비와 배뇨 장애가 동반된다.","focus":"긴급 신경학적 변화","action":"즉시 응급 평가를 요청하고 발생 시각을 알린다.","followup":"응급 인계와 움직임 지시를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-09","name":"통풍·급성 관절 통증","track":"근골격계","reason":"통풍 병력이 있어도 새 관절염 원인을 간병사가 확정하지 않는다.","scenario":"발가락 관절이 갑자기 붓고 뜨겁다.","focus":"급성 염증·감염 감별 필요","action":"압박을 피하고 통증·발열을 보고한다.","followup":"통증·발적 범위 변화를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-10","name":"근감소와 일상 기능","track":"근골격계","reason":"근력 저하는 낙상과 의존도에 영향을 준다. 무조건 침상 안정으로 해결하지 않는다.","scenario":"의자에서 일어나기가 점점 어려워졌다.","focus":"근력·영양·기능 저하","action":"안전한 도움 수준을 확인하고 재활·영양 평가를 요청한다.","followup":"기능 변화와 섭취 상태를 기록한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-11","name":"관절 구축 예방","track":"근골격계","reason":"관절을 억지로 끝까지 밀지 않는다. 통증·경직 변화는 재활팀에 알린다.","scenario":"침상 생활로 팔꿈치 펴기가 어려워진다.","focus":"움직임 제한과 관절 보호","action":"처방된 범위 내 운동·자세 보조를 수행한다.","followup":"운동 후 통증과 피부 상태를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-12","name":"보행기 사용","track":"근골격계","reason":"보조기 종류와 사용법은 개인 기능에 맞추어야 한다.","scenario":"보행기가 멀리 놓여 몸을 앞으로 과하게 뻗는다.","focus":"보조기 사용과 균형","action":"재활팀이 교육한 높이·순서·도움 수준을 확인한다.","followup":"휘청거림과 피로를 기록한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-13","name":"휠체어 이동","track":"근골격계","reason":"이동 방식과 인원은 평가된 기능에 따른다. 환자가 지탱하지 못하는 체중을 간병사가 대신 들어 올리면 환자가 떨어지거나 간병사가 허리를 다칠 수 있습니다. 체중 지지 능력이 달라졌다면 기존 이동 계획을 재확인하고 평가에 맞는 장비를 교육받은 인력과 사용합니다.","scenario":"브레이크를 잠그지 않은 채 일어서려 한다.","focus":"이승 전 장비 안전","action":"이동을 잠시 멈추고 브레이크·발판·동선을 점검한다.","followup":"이동 후 자세·압박·안전벨트 지시를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-14","name":"석고·보조기 압박","track":"근골격계","reason":"새 감각·색·온도 변화는 압박 문제의 신호일 수 있다.","scenario":"보조기 아래 손가락이 저리고 차갑다고 한다.","focus":"말초 순환·신경 변화","action":"즉시 보고하고 장치를 임의 절단하거나 조이지 않는다.","followup":"담당자 평가 후 말초 상태를 관찰한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-15","name":"수술 상처 변화","track":"근골격계","reason":"드레싱·소독 방법은 처방과 업무 범위를 따른다.","scenario":"정형외과 수술 상처의 진물과 열감이 늘었다.","focus":"상처 감염·회복 변화","action":"상처를 만지지 않고 새 변화와 발열을 보고한다.","followup":"평가 후 관찰 지시를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-16","name":"침상 생활과 혈전 의심","track":"근골격계","reason":"장기 부동 후 혈전 등 감별이 필요하다. 새 숨참이 동반되면 응급 호출한다.","scenario":"한쪽 종아리가 붓고 아프다.","focus":"편측 부종·통증","action":"마사지하지 않고 즉시 보고한다.","followup":"호흡과 통증 변화를 인계한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-17","name":"절단 후 일상 지원","track":"근골격계","reason":"의족 조절·피부 관리는 전문팀 계획을 따른다.","scenario":"의족 접촉 부위가 쓸리고 통증이 난다.","focus":"피부 손상과 보조기 적합성","action":"사용을 무리하게 이어가지 않고 담당팀에 알린다.","followup":"피부 회복과 이동 대안을 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-18","name":"지속 통증과 정서","track":"근골격계","reason":"통증은 수치뿐 아니라 기능과 환자 목표를 함께 살핀다. 수건을 세게 비틀면 손목이 꺾인 상태에서 반복해 힘을 쓰게 됩니다. 짜지 않아도 되는 준비 방식이나 탈수 도구를 사용하고 손목을 전완과 나란히 두세요. 통증·저림이 반복되면 어떤 작업에서 시작됐는지 일찍 보고하고 보건담당자나 의료진에게 평가를 받으세요.","scenario":"통증 때문에 잠을 못 자고 무기력해졌다.","focus":"통증의 수면·기분 영향","action":"통증 표현과 활동 영향을 듣고 담당자에게 전달한다.","followup":"치료 후 편안함과 활동 변화를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-19","name":"낙상 후 머리 손상","track":"근골격계","reason":"상처가 없다고 중대한 손상을 배제할 수 없다.","scenario":"넘어진 뒤 겉상처는 없지만 구토와 졸림이 생겼다.","focus":"낙상 후 지연성 악화","action":"즉시 응급 도움을 요청하고 낙상 시각·복약 정보를 알린다.","followup":"의식·호흡 관찰과 인계를 확인한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"},{"id":"M-20","name":"퇴원 후 재활 계획","track":"근골격계","reason":"회복 속도는 개인차가 있으며 과부하보다 단계적 계획이 중요하다.","scenario":"가족이 빨리 회복하라며 운동량을 두 배로 늘리려 한다.","focus":"개인별 재활 강도와 회복","action":"현재 운동·체중부하 지시를 함께 확인한다.","followup":"수행 가능한 목표와 재평가 일정을 공유한다.","source":"https://www.niams.nih.gov/health-topics/arthritis"}]},{"id":"respiratory","title":"호흡기질환 전문간병사","category":"질환군 교육","scope":"폐렴·흡인성 폐렴·COPD·폐기종·만성기관지염·천식·기관지확장증·간질성 폐질환·폐결핵·폐암","tracks":["호흡기 공통","폐렴·흡인","COPD·폐기종","천식·기타 폐질환","폐결핵","폐암"],"units":[{"id":"R01","name":"호흡기 구조·기능과 관찰","track":"호흡기 구조·기능과 관찰","reason":"폐포의 가스 교환, 기도의 공기 통과, 호흡 노력과 의식을 구분해 관찰한다. 산소포화도는 산소화의 한 단서이며 이산화탄소 배출이나 호흡 부담 전체를 보여주지 않는다. 평소와의 차이·발생 시각·활동 조건을 함께 기록한다.","scenario":"기기가 정상에 가까운 수치를 보이지만 환자는 새로 말을 잇기 어렵고 처진다.","focus":"수치와 환자 상태를 함께 평가해야 할 긴급 변화","action":"측정 완료를 기다리지 않고 즉시 도움을 요청한다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R02","name":"공통 돌봄·산소 안전","track":"공통 돌봄·산소 안전","reason":"산소 장치·설정·목표는 개인별 처방을 확인한다. 간병사는 외부 눌림·당김·점화원을 살피고 설정을 임의로 바꾸지 않는다. 식사·세안·이동은 호흡 부담과 삼킴·동반질환을 고려해 나누어 돕는다. 흡인과 환기 설정은 담당자의 영역이다.","scenario":"산소 줄이 눌린 상태에서 환자가 답답하다고 유량을 높여 달라고 한다.","focus":"산소 공급 환경과 새 증상의 동시 확인","action":"외부 눌림을 안전하게 해소하도록 돕고 즉시 담당자에게 상태를 알린다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R03","name":"폐렴·흡인성 폐렴","track":"폐렴·흡인성 폐렴","reason":"폐렴은 감염에 의한 폐 염증으로 호흡·전신 상태를 함께 관찰한다. 고령 환자는 발열이 뚜렷하지 않아도 새 혼돈·기능 저하를 보일 수 있다. 흡인 예방은 삼킴 평가·식이·구강 관리·자세 계획에 따른다. 기침이 없다고 흡인을 배제하지 않는다.","scenario":"식사 중 기침 뒤 호흡이 힘들고 평소보다 반응이 둔해졌다.","focus":"흡인 위험과 급성 호흡·의식 변화","action":"식사 보조를 멈추고 즉시 의료진을 호출한다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R04","name":"COPD·폐기종·만성기관지염","track":"COPD·폐기종·만성기관지염","reason":"COPD 교육에서는 폐기종의 폐조직 손상과 만성기관지염의 기도·분비물 문제를 구분한다. 평소 대비 숨참·가래·기능 변화를 보고한다. 산소는 무조건 금지하거나 최대치로 올리지 않고 개별 처방을 따른다. 호흡·활동 훈련은 전문팀의 교육을 지원한다.","scenario":"COPD 환자가 평소보다 숨차고 가래가 늘었지만 원래 아픈 병이라며 참는다.","focus":"기준 상태와 다른 악화 징후","action":"달라진 증상과 시각을 신속히 보고하고 개인별 계획을 확인한다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R05","name":"천식·기관지확장증·간질성 폐질환","track":"천식·기관지확장증·간질성 폐질환","reason":"천식의 기도 협착, 기관지확장증의 만성 기도·분비물 문제, 간질성 폐질환의 폐조직 변화를 구분한다. 같은 숨참이라도 관리법은 다르다. 천식에서 소리가 줄어도 탈진·말하기 곤란이 커지면 호전이라 단정하지 않는다.","scenario":"기관지확장증 환자가 새 객혈과 숨참을 보이는데 평소 배출 훈련을 계속하려 한다.","focus":"증상 변화 시 기존 훈련의 재평가","action":"훈련을 계속하기보다 즉시 의료진에게 출혈·호흡 변화를 알린다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R06","name":"폐결핵·감염관리","track":"폐결핵·감염관리","reason":"전염성 폐결핵 의심·확인 시 기관의 공기주의, 호흡보호구, 출입·이동 절차를 따른다. 격리실의 문·환기 장치를 임의 변경하지 않는다. 잠복결핵과 활동성 질환을 구분하며 격리 해제는 증상만으로 정하지 않는다. 치료 지속을 돕되 약 조정은 담당팀에 맡긴다.","scenario":"기침이 줄어든 결핵 환자가 격리실 문을 열고 공용 공간에 가겠다고 한다.","focus":"감염관리 지시와 격리 해제 판단의 구분","action":"담당 의료진·감염관리팀의 현재 이동·격리 지침을 먼저 확인한다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R07","name":"폐암·치료 전후 돌봄","track":"폐암·치료 전후 돌봄","reason":"폐암 돌봄은 치료·증상·기능·환자 목표별로 달라진다. 객혈, 얼굴·목 부종과 숨참, 치료 중 새 기침·오한은 신속히 알린다. 흉관 잠금·분리·짜내기를 임의로 하지 않는다. 통증·영양·호흡·정서 지원과 완화돌봄을 연계한다.","scenario":"폐암 치료 중 환자가 새 기침과 숨참을 보이지만 다음 예약까지 기다리려 한다.","focus":"감염·치료 부작용 등을 포함한 새 호흡 변화","action":"치료 정보와 발생 시각을 신속히 담당팀에 전달한다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"R08","name":"복합질환·응급 보고·인계","track":"복합질환·응급 보고·인계","reason":"복합질환에서는 한 질환의 일반 조언을 그대로 적용하지 않는다. 수분·식이·활동·장치 계획을 통합 확인한다. 기록은 호소·관찰·측정·의료진 판단을 구분한다. 악화가 지속되면 재호출하고, 퇴원 교육은 설명·시범으로 이해를 확인한다.","scenario":"폐렴·COPD·신장질환이 함께 있는 환자에게 가래를 묽게 하려고 물을 많이 주려 한다.","focus":"동반질환을 고려한 통합 계획","action":"삼킴과 신장 상태를 반영한 개인별 수분 지시를 확인한다.","followup":"대응 후 호흡·의식·편안함과 미해결 문제를 확인해 다음 담당자에게 인계한다.","source":"https://www.who.int/health-topics/lung-health"},{"id":"lung-U01","name":"호흡곤란의 주관성","track":"폐암","reason":"한 수치만으로 고통이나 위험을 배제하지 않는다. 호흡 노력·말하기·의식 변화도 중요하다.","scenario":"산소포화도가 평소와 비슷해도 환자는 숨이 몹시 차다고 호소한다.","focus":"수치와 별개로 존중해야 할 호흡 불편","action":"활동을 멈추고 편한 자세를 돕되 새롭거나 심한 호흡곤란은 즉시 보고한다.","followup":"증상 전후 활동과 의료진 대응 후 편안함을 확인한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U02","name":"객혈","track":"폐암","reason":"피의 양이 정확하지 않아도 호흡 악화는 긴급하다. 임의로 음료나 약을 먹이지 않는다.","scenario":"기침 뒤 선홍색 피가 나오며 호흡이 힘들어진다.","focus":"출혈을 동반한 호흡기 응급 변화","action":"즉시 응급 호출하고 교육받은 안전·기도 보조 절차를 따른다.","followup":"피의 모습·반복 여부·호흡과 의식 변화를 인계한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U03","name":"산소 사용 안전","track":"폐암","reason":"산소 주변에서는 연소 위험 관리가 필요하다. 유량을 줄여 불을 사용하게 하는 것은 대안이 아니다.","scenario":"처방된 산소를 사용하는 환자 옆에서 가족이 불꽃을 쓰려 한다.","focus":"산소 사용 환경의 화재 위험","action":"즉시 불꽃 사용을 막고 병원 산소 안전 규정을 안내한다.","followup":"산소 장치와 주변 점화원·안전 표지를 점검한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U04","name":"산소 장치 이상","track":"폐암","reason":"장치 이상과 질환 악화가 함께 있을 수 있다. 유량·장치 종류를 간병사가 임의로 변경하지 않는다.","scenario":"산소 줄이 꺾여 있고 환자가 평소보다 숨차다고 말한다.","focus":"공급 장치 상태와 임상 변화","action":"외부 꺾임을 안전하게 살피며 즉시 간호사를 부른다.","followup":"증상 지속 여부와 발견한 외부 이상을 전달한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U05","name":"흉관 배액 장치","track":"폐암","reason":"흉관은 일반 소변 주머니와 다르다. 임의로 잠그거나 분리하거나 짜내지 않는다.","scenario":"수술 후 환자를 옮기다가 흉관 장치가 넘어질 뻔하고 줄이 당겨진다.","focus":"배액 장치의 위치·연결 안전","action":"이동을 멈추고 간호사와 안전한 장치 위치를 확인한다.","followup":"당김·연결 이상·새 통증이나 숨참을 확인해 보고한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U06","name":"수술 후 움직임","track":"폐암","reason":"재활과 휴식은 수술별 계획을 따른다. 무리한 운동이나 전면적인 침상 안정으로 바꾸지 않는다.","scenario":"흉부 수술 후 기침할 때 아파서 움직임을 모두 피하려 한다.","focus":"통증이 호흡·활동에 미치는 영향","action":"통증을 보고하고 의료진이 교육한 지지·활동 방법을 돕는다.","followup":"통증 대응 후 허용 활동을 얼마나 수행했는지 기록한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U07","name":"새 기침과 치료","track":"폐암","reason":"감염·종양·치료 부작용을 간병사가 구분해 확정하지 않는다. 다음 예약까지 미루지 않는다.","scenario":"면역치료 중 평소와 다른 기침과 숨참이 생겼다.","focus":"치료 관련 폐 이상 등을 포함한 변화","action":"치료 종류·새 기침·호흡 변화 시각을 신속히 보고한다.","followup":"의료진 평가 전후 호흡과 활동 내성 변화를 살핀다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U08","name":"얼굴·목 부종","track":"폐암","reason":"부종을 단순히 살이 찐 것으로 해석하지 않는다. 마사지나 임의 이뇨제 투여는 하지 않는다.","scenario":"환자 얼굴과 목이 새로 붓고 눕기 불편하며 숨이 찬다.","focus":"혈류 장애 등을 포함한 긴급 변화","action":"즉시 의료진을 부르고 편한 허용 자세를 돕는다.","followup":"부종 발생 시각·자세와 증상의 관계를 기록한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U09","name":"피로와 호흡 절약","track":"폐암","reason":"속도를 강요하지 않고 환자의 목표와 회복 시간을 고려한다. 새 악화는 계획된 피로로 넘기지 않는다.","scenario":"세수와 옷 갈아입기를 연달아 하면 숨이 차지만 쉬면 회복된다.","focus":"일상 활동의 에너지 조절","action":"허용 범위에서 활동을 나누고 앉아서 할 수 있도록 돕는다.","followup":"활동·휴식 간격과 회복 정도를 기록한다.","source":"https://www.cancer.gov/types/lung"},{"id":"lung-U10","name":"불안과 숨참","track":"폐암","reason":"불안이 보여도 증상을 심리 문제만으로 치부하지 않는다. 안정된 관계와 원인 평가를 함께 제공한다.","scenario":"숨찬 환자가 불안해하며 혼자 두지 말아 달라고 한다.","focus":"심리적 지지와 신체 평가의 병행","action":"곁에서 짧게 말하며 안심을 돕고 호흡 변화를 의료진에게 알린다.","followup":"환자가 도움이 됐다고 한 방법과 호흡 경과를 전달한다.","source":"https://www.cancer.gov/types/lung"}]},{"id":"orthopedic","title":"정형외과질환 전문간병사","category":"질환군 교육","scope":"고관절·척추·상하지 골절, 관절 치환술·골절 고정술 후 회복, 석고·보조기 관리, 체중부하·이동·재활 안전","tracks":["정형외과"],"units":[{"id":"O-01","name":"고관절 골절 후 이동","track":"정형외과","reason":"고관절 골절 후 조기 이동은 팀 계획에 따라 진행한다. 수술별 지시가 다르므로 임의로 걷게 하지 않는다.","scenario":"고관절 수술 다음 날 보호자가 혼자 환자를 일으키려 한다.","focus":"수술 후 이동·체중부하 지시","action":"간호사·재활팀의 현재 도움 수준과 체중부하 지시를 확인하고 함께 이동을 돕는다.","followup":"이동 중 통증·어지럼·휘청거림과 도움 수준을 기록한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-02","name":"낙상 후 하지 변형","track":"정형외과","reason":"외형만으로 진단하지 않는다. 불필요한 움직임은 손상을 키울 수 있다.","scenario":"넘어진 뒤 다리 모양이 달라지고 심한 통증을 호소한다.","focus":"골절 가능성이 있는 낙상","action":"억지로 일으키거나 다리를 펴지 않고 즉시 도움을 요청한다.","followup":"낙상 시각·자세·환자 호소와 호출 시각을 전달한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-03","name":"석고 압박과 감각 변화","track":"정형외과","reason":"깁스 압박 아래의 저림·심한 부종·통증은 신속한 평가가 필요한 경고 신호다. 깁스를 자르거나 물체를 넣지 않는다.","scenario":"깁스한 발가락이 저리고 차가우며 붓기가 심해졌다.","focus":"말초 순환·감각의 새 변화","action":"즉시 담당자에게 알리고 발가락 색·온도·감각 변화를 확인한다.","followup":"보고 후 재평가 지시와 증상 변화를 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-04","name":"인공관절 수술 후 자세","track":"정형외과","reason":"모든 인공관절 환자에게 같은 자세 제한을 적용할 수 없다. 수술팀의 개별 계획을 따른다.","scenario":"고관절 수술 환자의 자세 제한이 인계에 적혀 있지 않다.","focus":"수술별 자세와 움직임 제한 확인","action":"옮기기 전에 담당팀의 최신 접근법별 지시를 확인한다.","followup":"확인한 자세·체중부하 지시를 교대 기록에 남긴다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-05","name":"무릎 인공관절 후 통증","track":"정형외과","reason":"회복 과정의 불편과 급격한 악화를 구분하려면 환자 상태와 계획을 확인해야 한다.","scenario":"재활 운동 뒤 무릎 통증이 평소보다 커지고 붓기가 늘었다.","focus":"운동 후 통증·부종 변화","action":"활동을 멈추고 통증과 부종 변화를 담당자에게 알린다.","followup":"증상 발생 시점과 활동·휴식 후 변화를 기록한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-06","name":"척추 수술 후 체위 변경","track":"정형외과","reason":"수술 종류와 고정 상태에 따라 허용 동작이 다르다. 간병사가 견인하거나 임의 운동을 시키지 않는다.","scenario":"척추 수술 뒤 침대에서 몸을 비틀어 일어나려 한다.","focus":"수술 부위 보호와 안전한 이동","action":"수술 후 이동 교육과 인력 도움 계획을 확인해 함께 체위 변경한다.","followup":"이동 후 통증·저림·새 근력 변화를 확인해 보고한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-07","name":"척추 손상 의심","track":"정형외과","reason":"저림·마비는 긴급 평가가 필요할 수 있다. 목이나 등을 맞추려 하지 않는다.","scenario":"목을 다친 환자가 손발 저림과 힘 빠짐을 새로 호소한다.","focus":"급성 신경학적 변화","action":"불필요하게 움직이지 않게 하고 즉시 응급 도움을 요청한다.","followup":"발생 시각과 손상 상황, 환자 호소를 정확히 인계한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-08","name":"허리 통증과 배뇨 변화","track":"정형외과","reason":"새 신경 증상과 배뇨 변화는 기존 만성 요통과 다르게 긴급 평가가 필요하다.","scenario":"요통에 새 다리 힘 빠짐과 배뇨 곤란이 함께 나타난다.","focus":"척추 신경 압박 가능성의 경고 변화","action":"마사지·운동을 하지 말고 즉시 담당 의료진에게 알린다.","followup":"증상 시작 시각과 함께 나타난 변화를 보고한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-09","name":"골절 고정술 후 상처","track":"정형외과","reason":"상처 관리·드레싱 교환은 지침과 업무 범위를 따른다. 감염을 스스로 진단하지 않는다.","scenario":"수술 상처의 열감·붉어짐과 진물이 늘었다.","focus":"수술 상처의 감염 의심 변화","action":"상처나 드레싱을 임의로 만지지 않고 발열 여부와 함께 즉시 보고한다.","followup":"담당팀 평가와 이후 관찰 지시를 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-10","name":"골절 후 체중부하 지시","track":"정형외과","reason":"통증 감소가 뼈가 체중을 견딜 준비가 되었다는 뜻은 아니다.","scenario":"환자가 통증이 적다며 보행기 없이 걸으려 한다.","focus":"허용된 체중부하와 이동 보조","action":"최신 지시를 확인하고 정해진 보조기·인력으로 이동하도록 돕는다.","followup":"이동 시 보조 방식과 환자 반응을 기록한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-11","name":"어깨 골절과 옷 갈아입기","track":"정형외과","reason":"팔을 당기거나 장치를 임의로 풀지 않는다. 허용된 움직임을 확인한다.","scenario":"팔걸이 붕대를 한 환자가 혼자 소매를 당겨 입으려 한다.","focus":"손상 부위 보호와 자립 지원","action":"환자 의사를 묻고 교육받은 방법으로 옷을 입도록 보조한다.","followup":"불편·피부 압박·도움이 필요했던 동작을 살핀다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-12","name":"손목 골절과 보조기","track":"정형외과","reason":"보조기를 임의로 조이거나 풀지 않는다. 새 감각·순환 변화는 평가가 필요하다.","scenario":"보조기 아래 피부가 쓸리고 손가락이 붓는다.","focus":"피부 손상과 말초 순환 변화","action":"손가락 색·온도·감각과 피부 변화를 보고하고 재조정은 담당자에게 요청한다.","followup":"압박 부위와 평가 후 관리 지시를 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-13","name":"골다공증 환자 이승","track":"정형외과","reason":"낙상은 취약 골절로 이어질 수 있다. 팔을 잡아당겨 급히 일으키지 않는다.","scenario":"골다공증 환자가 낮은 의자에서 일어날 때 휘청거린다.","focus":"취약 골절과 낙상 예방","action":"환경을 정리하고 개인별 이승 방법과 보조 인력을 확인한다.","followup":"이승 후 통증·균형과 필요한 도움 수준을 기록한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-14","name":"골절 후 섬망·혼돈","track":"정형외과","reason":"급성 혼돈은 통증·감염·약물 등 원인 평가가 필요하다. 성격 변화나 치매로 단정하지 않는다.","scenario":"골절 수술 뒤 환자가 평소와 달리 밤에 혼란스러워한다.","focus":"수술 후 급성 인지 변화","action":"안전하게 곁을 지키고 발생 시각·수면·통증·동반 변화를 보고한다.","followup":"의료진에 전달한 내용과 환자 반응을 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-15","name":"부동 후 한쪽 종아리 부종","track":"정형외과","reason":"수술·부동 후 편측 부종은 평가가 필요한 변화다. 마사지로 해결하지 않는다.","scenario":"수술 뒤 한쪽 종아리가 붓고 아프며 따뜻하다.","focus":"편측 부종·통증과 혈전 의심","action":"다리를 마사지하지 말고 즉시 의료진에게 알린다. 새 숨참이 있으면 응급 호출한다.","followup":"증상 시작 시각과 호흡·통증 변화를 인계한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-16","name":"보행기와 수술 후 보행","track":"정형외과","reason":"수술 후 보행은 장비·체중부하·도움 수준을 함께 확인해야 한다.","scenario":"보행기가 멀리 있는데 환자가 혼자 일어나려 한다.","focus":"장비 위치·균형·낙상 위험","action":"이동을 시작하기 전 호출하고 보행기를 가까이 둔 뒤 교육받은 순서를 따른다.","followup":"이동 후 피로·통증·균형과 필요한 도움을 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-17","name":"관절염과 아침 경직","track":"정형외과","reason":"통증을 참게 하거나 관절을 강제로 끝까지 움직이지 않는다.","scenario":"손 관절이 뻣뻣해 세면과 단추 잠그기가 힘들다.","focus":"관절 기능과 자기관리 지원","action":"시간을 충분히 주고 보조 도구와 환자가 원하는 도움을 확인한다.","followup":"도움이 효과적이었던 방법과 통증 변화를 공유한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-18","name":"절단 후 피부 손상","track":"정형외과","reason":"의족 조정과 상처 치료는 전문팀 계획에 따른다.","scenario":"의족을 착용한 뒤 절단단 끝에 붉은 자국과 통증이 생긴다.","focus":"피부 압박·상처와 보조기 적합성","action":"의족 착용을 계속 강요하지 말고 피부 상태와 통증을 담당팀에 알린다.","followup":"피부 변화와 대체 이동 지원 계획을 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-19","name":"정형외과 퇴원 후 재활","track":"정형외과","reason":"회복을 앞당기려는 임의 운동 증량은 통증·낙상 위험을 키울 수 있다.","scenario":"가족이 정해진 운동량보다 더 많이 걷게 하려 한다.","focus":"개별 재활 목표·금기·체중부하 확인","action":"퇴원 안내와 재활팀 계획을 함께 확인하고 정해진 범위에서 보조한다.","followup":"수행한 활동·증상·다음 확인 일정을 기록한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"},{"id":"O-20","name":"야간 골절 통증","track":"정형외과","reason":"간병사는 진통제를 추가하거나 통증 원인을 진단하지 않는다.","scenario":"환자가 갑자기 심해진 수술 부위 통증 때문에 잠을 못 잔다.","focus":"새 통증과 기능 변화","action":"통증의 위치·강도·시각·활동과의 관계를 듣고 담당자에게 보고한다.","followup":"보고 후 계획과 통증 변화를 확인한다.","source":"https://orthoinfo.aaos.org/globalassets/pdfs/cast-care.pdf"}]},{"id":"infection","title":"감염질환 전문간병사","category":"질환군 교육","scope":"표준주의·손 위생·보호구·격리 안내, 호흡기·접촉 감염, 요로·수술상처 감염 의심, 면역저하 환자 발열, 체액 노출·환경 관리","tracks":["감염질환"],"units":[{"id":"I-01","name":"표준주의와 손 위생","track":"감염질환","reason":"표준주의는 감염 여부를 모르는 환자를 포함해 모든 돌봄에 적용한다. 장갑은 손 위생을 대신하지 않는다.","scenario":"환자 접촉 뒤 같은 장갑으로 침대 주변 물품을 정리하려 한다.","focus":"접촉 전후 손 위생과 장갑 교체","action":"장갑을 벗고 손 위생을 한 뒤 업무와 오염 위험에 맞는 새 보호구를 사용한다.","followup":"손 위생 시점과 물품 교체를 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-02","name":"호흡기 증상과 기침 예절","track":"감염질환","reason":"전파 경로와 기관 지침에 따라 필요한 예방조치가 다르다. 간병사가 격리 해제를 결정하지 않는다.","scenario":"기침·콧물이 있는 환자가 마스크 없이 공용 공간으로 가려 한다.","focus":"호흡기 분비물 전파 위험","action":"기관의 현재 격리·이동 지침을 확인하고 기침 예절과 손 위생을 돕는다.","followup":"이동 승인과 보호 조치, 환자 반응을 인계한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-03","name":"결핵 격리 절차","track":"감염질환","reason":"증상 호전만으로 전염성이나 격리 해제를 판단할 수 없다. 보호구 교육을 확인한다.","scenario":"기침이 줄었다며 결핵 격리 환자가 병실 문을 열고 나가려 한다.","focus":"공기주의와 이동 지시 확인","action":"감염관리팀·담당자의 현재 격리 및 이동 지침을 따르고 즉시 알린다.","followup":"지침 확인자와 이동 후속 계획을 기록한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-04","name":"인플루엔자 환자 돌봄","track":"감염질환","reason":"손 위생, 호흡기 예절, 적절한 보호구와 장비 소독은 전파 예방의 일부다.","scenario":"병동에 독감 환자가 있고 체온계·혈압계를 여러 환자에게 공용으로 쓰려 한다.","focus":"호흡기 감염 예방과 장비 관리","action":"환자별 장비를 쓰거나 기관의 세척·소독 절차를 따른다.","followup":"사용 장비와 정리·소독 완료 여부를 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-05","name":"코로나 유사 증상","track":"감염질환","reason":"검사 결과 전에도 감염 예방 절차를 적용할 수 있다. 간병사가 감염을 확정하지 않는다.","scenario":"환자가 새 기침과 숨참을 보이지만 검사 결과가 아직 없다.","focus":"검사 전 증상 대응과 조기 보고","action":"기관 지침에 맞는 보호구를 사용하고 새 증상을 즉시 보고한다.","followup":"발생 시각·증상·보고 및 지침을 인계한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-06","name":"감염 환자 체액 노출","track":"감염질환","reason":"노출 후 조치와 평가 시점은 기관 지침에 따른다. 혼자 판단해 기다리지 않는다.","scenario":"환자 체액이 눈에 튀었다.","focus":"직업성 노출과 즉시 보고","action":"기관의 노출 대응 절차에 따라 씻고 즉시 관리자·의료진에게 보고한다.","followup":"노출 시각·체액·보호구·실시한 조치를 보고한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-07","name":"설사와 접촉주의","track":"감염질환","reason":"병원체별 손 위생·환경 관리 지침이 다를 수 있어 감염관리 절차를 따른다.","scenario":"설사 환자 방을 나온 뒤 장갑만 벗고 다음 환자를 돌보려 한다.","focus":"접촉주의·손 위생·환경 관리","action":"보호구를 올바르게 벗고 손 위생을 한 뒤 기관 지침에 따라 다음 환자와 접촉한다.","followup":"보호구 폐기와 손 위생 완료를 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-08","name":"항생제 관련 설사","track":"감염질환","reason":"항생제 관련 설사는 평가가 필요할 수 있다. 약을 중단하거나 감염을 진단하지 않는다.","scenario":"항생제 복용 중인 환자가 잦은 물설사를 한다.","focus":"새 설사·탈수 위험과 감염관리 필요","action":"횟수·시작 시각·동반 증상을 기록하고 즉시 보고하며 배설물 취급 지침을 따른다.","followup":"수분 상태 관찰·격리 지침·담당자 계획을 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-09","name":"요로감염 의심 변화","track":"감염질환","reason":"노인 환자의 새 혼돈은 다양한 원인이 있을 수 있다. 소변 냄새만으로 감염을 진단하지 않는다.","scenario":"도뇨관이 있는 환자가 새 혼돈과 오한을 보인다.","focus":"감염 가능성과 급성 상태 변화","action":"활력·의식 변화를 즉시 간호사에게 알리고 도뇨관을 조작하지 않는다.","followup":"보고 시각과 이후 상태·검사 계획을 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-10","name":"수술 상처 감염 의심","track":"감염질환","reason":"상처 처치 방법은 교육·업무 범위와 의료진 지시에 따른다.","scenario":"상처 주위가 붉고 뜨거우며 고름 같은 배액이 생겼다.","focus":"상처 변화와 감염 가능성","action":"상처를 만지거나 드레싱을 교체하지 않고 발열·통증 변화와 함께 보고한다.","followup":"보고 후 상처 관찰·드레싱 계획을 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-11","name":"혈액암·면역저하 환자 발열","track":"감염질환","reason":"면역저하 환자의 발열은 신속한 평가가 필요하다. 해열제나 격리 여부를 임의 결정하지 않는다.","scenario":"항암치료 환자가 오한과 열감을 말한다.","focus":"면역저하 상황의 새 발열·오한","action":"체온 측정이 지연되더라도 즉시 담당 의료진에게 알리고 지시된 보호 조치를 따른다.","followup":"발생 시각·치료 정보·측정값과 단위를 전달한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-12","name":"욕창 상처 감염 변화","track":"감염질환","reason":"상처 관리와 드레싱은 담당자 지시에 따른다. 냄새만으로 감염 여부를 단정하지 않는다.","scenario":"욕창 부위의 분비물·악취와 주변 발적이 늘었다.","focus":"상처·주변 피부의 새 변화","action":"상처를 직접 세척하거나 약을 바르지 않고 변화와 발열 여부를 보고한다.","followup":"상처 관찰 계획과 압박 완화 계획을 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-13","name":"다제내성균 표지","track":"감염질환","reason":"집락과 감염은 다르지만 전파 예방 절차는 기관 지침에 따라 수행한다.","scenario":"다제내성균 표지가 있는 환자의 물품을 복도 공용 카트에 놓는다.","focus":"환자 전용 물품·접촉 예방","action":"기관의 격리 표지와 물품 전용·세척 절차를 확인해 분리한다.","followup":"물품 분리와 소독 완료를 인계한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-14","name":"대상포진 의심 발진","track":"감염질환","reason":"병변 범위·면역 상태에 따라 필요한 예방조치가 다르다. 간병사는 진단하지 않는다.","scenario":"한쪽 피부에 물집이 모여 생기고 통증을 호소한다.","focus":"새 발진·접촉 위험과 조기 보고","action":"발진을 만지지 않고 가리며 즉시 담당자에게 알리고 격리 지침을 확인한다.","followup":"발진 시작 시각·범위와 접촉 지침을 공유한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-15","name":"구토·설사 동시 발생","track":"감염질환","reason":"집단 발생 의심 시 신속한 보고와 환경 관리가 중요하다. 임의로 청소제를 혼합하지 않는다.","scenario":"같은 병실 두 환자가 갑자기 구토와 설사를 한다.","focus":"집단 발생 가능성과 환경 오염","action":"접촉을 줄이고 오염구역에 대한 기관 대응·보호구·청소 지침을 즉시 요청한다.","followup":"발생 인원·시각·공통 노출과 보고 경로를 기록한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-16","name":"혈액·체액 오염 세탁물","track":"감염질환","reason":"오염 세탁물 취급은 체액 노출을 피하도록 기관 지침을 따른다.","scenario":"오염된 침구를 털어 카트에 옮기려 한다.","focus":"비산·환경 오염 예방","action":"털거나 몸에 안지 말고 누출 없는 지정 용기에 넣는 기관 절차를 따른다.","followup":"포장·운반·보호구 처리 여부를 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-17","name":"감염 의심 환자 이동","track":"감염질환","reason":"환자 이동은 병원체별 지침과 검사실 사전 통보에 따라 조정한다.","scenario":"격리 환자를 검사실에 데려가라는 요청을 받았지만 이동 시 주의사항이 없다.","focus":"이동 전 감염관리·보호 조치 확인","action":"담당자와 감염관리 지침을 확인하고 환자·이동자 보호 조치를 갖춘다.","followup":"이동 승인·보호구·도착 부서 통보를 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-18","name":"손 위생 시설 부족","track":"감염질환","reason":"손 위생은 환자 접촉 전후에 필요하다. 빈 용기를 건너뛰지 않는다.","scenario":"환자 접촉 전 손 소독제가 비어 있는 것을 발견했다.","focus":"손 위생 수행 환경과 대체 절차","action":"기관이 정한 대체 손 위생 장소를 이용하고 비품 부족을 보고한다.","followup":"비품 보충 요청과 손 위생 완료를 확인한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-19","name":"기침 환자의 가족 방문","track":"감염질환","reason":"방문 제한·마스크 등 조치는 기관 정책과 환자별 위험에 따른다.","scenario":"가족이 감기 증상이 있는데 마스크 없이 병실에서 식사하려 한다.","focus":"방문객 호흡기 예절과 환자 보호","action":"방문 정책을 안내하고 담당자에게 연결해 환자와 방문객을 보호한다.","followup":"방문 조정 결과와 환자 의사를 기록한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"},{"id":"I-20","name":"감염 예방 물품 공유","track":"감염질환","reason":"보호구는 예상 노출 위험과 기관 지침에 맞게 사용한다.","scenario":"보호안경과 앞치마를 여러 환자에게 그대로 사용하려 한다.","focus":"개인 보호구의 적절한 사용·재처리","action":"일회용 여부와 제조사·기관 재처리 지침을 확인하고 교체 또는 세척한다.","followup":"사용 후 폐기·소독 상태와 부족 물품을 인계한다.","source":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html"}]},{"id":"circulatory","title":"순환계질환 전문간병사","category":"질환군 교육","scope":"심부전·관상동맥질환·부정맥·고혈압·말초혈관질환·항응고 안전·심폐 복합질환","tracks":["순환계"],"units":[{"id":"C-01","name":"심부전·누우면 숨참","track":"순환계","reason":"심부전 등 여러 원인이 가능하며 간병사가 원인을 확정하지 않는다.","scenario":"누우면 숨이 차 베개를 더 달라고 한다.","focus":"새 자세 관련 호흡곤란","action":"편안한 상체 자세를 돕고 즉시 의료진에게 알린다.","followup":"호흡·의식과 담당자 지시를 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-02","name":"부종·체중 변화","track":"순환계","reason":"체중 하나보다 추세·호흡·배뇨를 함께 살핀다. 이뇨제를 임의로 늘리지 않는다.","scenario":"평소보다 발목이 붓고 체중이 늘었다.","focus":"체액 변화 추세","action":"같은 조건의 기록을 확인해 담당자에게 보고한다.","followup":"개인별 보고 기준과 반응을 기록한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-03","name":"급성 관상동맥 증상","track":"순환계","reason":"통증이 심하지 않거나 전형적이지 않아도 평가가 필요할 수 있다.","scenario":"가슴 압박감에 식은땀과 메스꺼움이 생겼다.","focus":"급성 심장질환 가능성","action":"활동을 멈추고 즉시 응급 도움을 요청한다.","followup":"시각·증상·응급 인계를 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-04","name":"협심증과 활동","track":"순환계","reason":"익숙한 증상이라도 새 양상·악화는 보고한다.","scenario":"걷다가 새 가슴 불편을 호소한다.","focus":"활동 중 흉부 증상","action":"걷기를 중단하고 현재 증상과 개인 응급 계획을 확인해 호출한다.","followup":"휴식 후에도 남은 증상을 인계한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-05","name":"부정맥·두근거림","track":"순환계","reason":"맥박 느낌만으로 부정맥 유형을 진단할 수 없다.","scenario":"심하게 두근거리면서 어지럽다고 한다.","focus":"심계항진과 순환 불안정","action":"안전한 자세를 돕고 즉시 보고한다.","followup":"실신·흉통·숨참 여부를 함께 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-06","name":"실신","track":"순환계","reason":"단순 피로로 단정하거나 의식이 불완전한 상태에서 물을 주지 않는다.","scenario":"일어나던 환자가 잠시 의식을 잃었다.","focus":"일시적 의식 소실","action":"기관 응급 절차에 따라 반응·호흡을 확인하고 도움을 요청한다.","followup":"회복 시각과 손상 여부를 기록한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-07","name":"기립성 어지럼","track":"순환계","reason":"약물·탈수 등 원인 평가가 필요하며 개인별 이동 계획을 따른다.","scenario":"침상에서 급히 일어난 뒤 눈앞이 캄캄하다고 한다.","focus":"자세 변화와 낙상 위험","action":"앉거나 눕도록 안전하게 돕고 상태를 보고한다.","followup":"천천히 이동할 때의 반응을 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-08","name":"고혈압과 새 신경 증상","track":"순환계","reason":"증상과 수치를 함께 전달하되 측정을 반복하느라 호출을 지연하지 않는다.","scenario":"높은 혈압과 함께 새 말 어눌함이 생겼다.","focus":"혈압 수치와 급성 장기 증상","action":"즉시 응급 도움을 요청하고 약을 임의 추가하지 않는다.","followup":"발생 시각과 응급 인계를 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-09","name":"저혈압 의심과 처짐","track":"순환계","reason":"수치 확인 전에도 심각한 상태 변화는 보고한다.","scenario":"환자가 창백하고 차가운 땀을 흘리며 처진다.","focus":"저관류 가능성이 있는 전신 변화","action":"즉시 호출하고 안전한 자세·호흡을 확인한다.","followup":"의식·호흡의 지속 변화를 관찰한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-10","name":"말초동맥질환","track":"순환계","reason":"온열기·강한 마사지로 해결하려 하지 않는다.","scenario":"발이 평소보다 차갑고 통증이 심하다.","focus":"사지 혈류 저하 가능성","action":"새 색·온도·통증 변화를 신속히 보고한다.","followup":"피부 손상과 담당자 계획을 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-11","name":"정맥성 부종","track":"순환계","reason":"부종의 원인은 다양하므로 기존 진단만으로 새 변화를 설명하지 않는다.","scenario":"오래 앉으면 다리가 붓지만 오늘 한쪽만 더 아프다.","focus":"기존 부종과 새 편측 변화","action":"변화를 보고하고 압박도구를 임의로 추가하지 않는다.","followup":"통증·피부·호흡 변화를 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-12","name":"항응고제와 출혈","track":"순환계","reason":"멍·잇몸 출혈·혈뇨 등도 관찰하되 약 중단 결정은 의료진에게 맡긴다.","scenario":"항응고제 복용 중 검은 변과 어지럼이 나타났다.","focus":"출혈 가능성과 순환 증상","action":"즉시 보고하고 복약 정보를 전달한다.","followup":"출혈·의식 변화와 평가 후 계획을 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-13","name":"심장 시술 후 부위","track":"순환계","reason":"시술별 움직임 제한과 관찰 방법을 확인한다.","scenario":"시술한 사타구니 주변이 붓고 피가 늘었다.","focus":"시술 부위 출혈","action":"즉시 담당자를 호출하고 현재 안정 지시를 따른다.","followup":"출혈 진행과 어지럼을 인계한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-14","name":"심박동기 삽입 후","track":"순환계","reason":"장치 설정·상처 처치는 전문 담당자의 업무다.","scenario":"삽입 부위가 붉고 열이 난다.","focus":"장치 삽입 부위 이상","action":"부위를 건드리지 않고 변화와 발열을 보고한다.","followup":"평가 후 활동·상처 관찰 계획을 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-15","name":"심장재활","track":"순환계","reason":"처방된 강도에서도 증상 변화에 따라 재평가한다.","scenario":"운동 중 숨참과 흉통이 새로 생겼다.","focus":"운동 중단이 필요한 증상","action":"운동을 멈추고 즉시 재활팀·의료진을 호출한다.","followup":"증상과 시행 활동을 기록한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-16","name":"수분·염분 계획","track":"순환계","reason":"모든 환자에게 동일한 제한이나 권장량을 적용하지 않는다.","scenario":"심부전과 신장질환 환자에게 물을 많이 마시라고 권한다.","focus":"동반 질환별 섭취 조정","action":"개인별 수분·식이 지시를 확인한다.","followup":"섭취·부종·배뇨 추세를 공유한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-17","name":"감염과 심장 증상","track":"순환계","reason":"감염 등 스트레스 상황에서 기존 질환이 악화될 수 있다.","scenario":"심장질환 환자가 발열 뒤 숨참과 피로가 심해졌다.","focus":"전신 질환에 동반한 심폐 악화","action":"새 변화와 체온·호흡을 보고한다.","followup":"평소 기능과의 차이를 인계한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-18","name":"심폐 복합질환","track":"순환계","reason":"같은 숨참이라도 원인이 다를 수 있어 통합 평가가 필요하다.","scenario":"COPD와 심부전이 있는 환자의 숨참 원인을 단정하려 한다.","focus":"겹치는 호흡·순환 증상","action":"원인을 단정하지 않고 발생·자세·부종·가래 변화를 전달한다.","followup":"호흡기·순환기 계획의 일치 여부를 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-19","name":"응급 호출과 소생술 연결","track":"순환계","reason":"응급 대응은 기관 지침·사전 의료계획과 본인의 훈련 범위에 따른다.","scenario":"환자가 반응이 없고 정상 호흡을 하지 않는다.","focus":"심정지 의심 응급 상황","action":"즉시 응급 호출하고 교육받은 심폐소생술·AED 절차를 따른다.","followup":"구조팀 도착과 인계 내용을 기록한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"},{"id":"C-20","name":"퇴원 후 악화 신호","track":"순환계","reason":"일반 수치를 외우게 하기보다 개인별 계획 이해를 확인한다.","scenario":"퇴원 환자가 언제 병원에 연락할지 모르겠다고 한다.","focus":"개인별 악화 기준 이해","action":"증상·연락처·복약·활동 계획을 설명하고 다시 말해 보도록 돕는다.","followup":"연락 경로와 도움 요청 가능성을 확인한다.","source":"https://www.nhlbi.nih.gov/health/heart-failure/symptoms"}]},{"id":"sensory","title":"감각계질환 전문간병사","category":"질환군 교육","scope":"백내장·녹내장·황반변성·난청·이명·균형장애·후각·미각·감각 저하","tracks":["감각계"],"units":[{"id":"S-01","name":"백내장과 눈부심","track":"감각계","reason":"백내장 등 원인은 안과 평가로 확인한다. 밝을수록 무조건 좋다고 보지 않는다.","scenario":"밝은 창가에서 더 잘 안 보인다고 한다.","focus":"눈부심과 흐린 시야","action":"빛 반사를 줄이고 대비가 분명한 환경을 마련한다.","followup":"환경 조정 후 이동·읽기 편안함을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-02","name":"녹내장과 시야","track":"감각계","reason":"녹내장은 초기 증상이 적을 수 있고 시야 손상을 동반할 수 있다.","scenario":"옆의 물건에 자주 부딪힌다.","focus":"주변 시야 제한과 이동 안전","action":"동선을 정리하고 접근 방향을 말로 알린다.","followup":"장애물 인지와 진료 계획을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-03","name":"급성 안통","track":"감각계","reason":"기존 안질환이 있어도 급성 변화는 별도 평가한다.","scenario":"눈 통증·충혈과 갑작스러운 시력저하가 생겼다.","focus":"응급 안과 평가가 필요한 변화","action":"즉시 의료진에게 알리고 임의 안약을 넣지 않는다.","followup":"발생 시각과 동반 증상을 인계한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-04","name":"황반변성","track":"감각계","reason":"황반은 중심 시력과 관련된다. 갑작스러운 왜곡을 단순 노화로 넘기지 않는다.","scenario":"얼굴 중심이 흐리고 글자가 휘어 보인다고 한다.","focus":"중심 시야 변화","action":"새 변화를 신속히 알리고 확대·대비 등 보조 방법을 확인한다.","followup":"일상 읽기·식사 도움 수준을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-05","name":"당뇨망막병증","track":"감각계","reason":"눈 질환은 증상이 적어도 검진이 중요하며 갑작스러운 변화는 따로 알린다.","scenario":"당뇨 환자가 시야에 새 검은 점이 늘었다.","focus":"새 시각 증상","action":"빠르게 안과 평가를 요청하고 변화를 전달한다.","followup":"평가 일정과 안전한 이동 계획을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-06","name":"망막 이상 의심","track":"감각계","reason":"증상만으로 진단하지 않되 기다리며 지켜보기만 하지 않는다.","scenario":"번쩍임과 커튼 같은 시야 가림이 갑자기 생겼다.","focus":"급성 시야 결손","action":"즉시 의료진에게 알리고 긴급 안과 평가를 연결한다.","followup":"시작 시각·한쪽 여부를 인계한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-07","name":"저시력 식사 지원","track":"감각계","reason":"가능한 자기 식사를 보존하고 무조건 대신 먹이지 않는다.","scenario":"음식 위치를 몰라 식사를 포기한다.","focus":"잔존 시력과 공간 안내","action":"동의를 구해 접시 위치를 일정하게 놓고 구체적으로 설명한다.","followup":"섭취와 자립 수준을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-08","name":"시각장애 이동 안내","track":"감각계","reason":"안내는 환자 선호와 전문 교육 방법을 따른다.","scenario":"팔을 갑자기 잡아끌자 환자가 놀란다.","focus":"예고·동의와 보행 안내","action":"먼저 자신을 소개하고 원하는 안내 방법을 묻는다.","followup":"장애물·계단 정보를 이해했는지 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-09","name":"안과 수술 후","track":"감각계","reason":"안대·세안·활동·안약은 수술별 지시를 따른다.","scenario":"수술 후 갑자기 눈 통증이 심해졌다.","focus":"수술 후 새 통증·시력 변화","action":"즉시 수술팀에 알리고 눈을 비비지 않도록 돕는다.","followup":"새 증상과 평가 후 계획을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-10","name":"안약 지원","track":"감각계","reason":"용기 끝 접촉·약 공유를 피하고 임의 투약하지 않는다.","scenario":"여러 안약을 쓰는데 어떤 것을 넣었는지 혼동한다.","focus":"투약 확인과 오염 예방","action":"처방·담당자와 확인하고 업무 범위 내에서 지원한다.","followup":"담당자가 확인한 사용 기록을 인계한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-11","name":"노인성 난청","track":"감각계","reason":"못 들은 반응을 치매로 단정하지 않는다. 무조건 소리 지르기보다 이해를 확인한다.","scenario":"말을 잘못 듣고 엉뚱하게 답한다.","focus":"청력 저하와 의사소통","action":"얼굴을 보며 주변 소음을 줄이고 또렷하게 말한다.","followup":"효과적인 거리·표현을 공유한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-12","name":"돌발성 난청","track":"감각계","reason":"돌발성 청력 소실은 지연 없이 평가할 증상이다.","scenario":"아침부터 한쪽 귀가 갑자기 잘 들리지 않는다.","focus":"급격한 청력 변화","action":"즉시 의료진에게 알리고 신속한 이비인후과 평가를 요청한다.","followup":"발생 시각·어지럼·이명을 인계한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-13","name":"보청기 일상 관리","track":"감각계","reason":"기기를 임의 분해하거나 귀 안에 도구를 넣지 않는다.","scenario":"보청기를 끼워도 들리지 않는다고 한다.","focus":"기기 상태와 청력 변화 구분","action":"교육받은 범위에서 전원·배터리·착용을 확인한다.","followup":"개선되지 않으면 전문 담당자에게 연결한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-14","name":"이명과 수면","track":"감각계","reason":"새 청력저하나 신경 증상을 동반하면 신속히 보고한다.","scenario":"귀 울림 때문에 잠을 못 자 불안해한다.","focus":"이명의 기능·정서 영향","action":"불편을 듣고 수면·발생 양상을 기록해 상담을 연결한다.","followup":"수면과 불안의 변화를 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-15","name":"어지럼과 균형","track":"감각계","reason":"귀 문제뿐 아니라 신경·순환 등 원인이 가능하다. 임의 머리 회전 치료를 하지 않는다.","scenario":"일어설 때 주변이 도는 듯하며 넘어질 뻔했다.","focus":"어지럼과 낙상 위험","action":"안전하게 앉도록 돕고 새 증상을 보고한다.","followup":"동반 마비·말 변화가 있으면 즉시 응급 호출한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-16","name":"이중 감각장애","track":"감각계","reason":"동의 없이 만지거나 반응이 없다고 의사가 없다고 단정하지 않는다.","scenario":"잘 보이지도 들리지도 않아 설명을 이해하지 못한다.","focus":"시청각 복합 장벽","action":"선호하는 접촉·문자·보조수단을 확인하고 천천히 전달한다.","followup":"사용 가능한 의사소통 방식을 인계한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-17","name":"후각 저하와 안전","track":"감각계","reason":"후각 변화는 식욕과 위험 인지에 영향을 줄 수 있다.","scenario":"음식이 상한 냄새를 맡지 못한다고 한다.","focus":"후각 저하와 생활 위험","action":"유통·보관 상태를 확인하고 냄새에 의존하지 않는 안전 계획을 따른다.","followup":"섭취·안전 장치와 새 증상을 확인한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-18","name":"미각 변화와 영양","track":"감각계","reason":"간병사가 소금·당을 무제한 늘리기보다 영양 계획을 확인한다.","scenario":"맛이 달라졌다며 식사를 거의 안 한다.","focus":"미각·구강 상태와 섭취 저하","action":"구강 불편·치료·약물 정보를 보고하고 허용된 식이를 조정하도록 요청한다.","followup":"섭취량과 선호 변화를 기록한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-19","name":"감각 저하와 화상","track":"감각계","reason":"감각이 둔하면 손상을 늦게 알 수 있다.","scenario":"발 감각이 둔한 환자가 뜨거운 찜질을 원한다.","focus":"통증 인지 저하와 열 손상","action":"직접 열원을 대지 않고 안전한 방법을 담당자에게 확인한다.","followup":"피부 색·물집·상처를 관찰한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"},{"id":"S-20","name":"감각 지원과 인지 평가","track":"감각계","reason":"인지 변화 평가는 감각·언어·환경 영향을 함께 고려한다.","scenario":"안경과 보청기 없이 질문에 답하지 못해 치매가 심해졌다고 한다.","focus":"평가 전 감각·언어 장벽","action":"보조기와 이해 가능한 설명을 준비하고 반응을 다시 전달한다.","followup":"지원 전후 반응 차이를 기록한다.","source":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases"}]},{"id":"neurological","title":"신경계·정신질환 전문간병사","category":"질환군 교육","scope":"뇌졸중(뇌경색·뇌출혈)·파킨슨병·뇌종양·우울·불안·정신증·수면·자해 위험. 치매는 독립 과정에서 심화 학습","tracks":["뇌질환(뇌경색·뇌출혈)","파킨슨","뇌암","정신건강·우울"],"units":[{"id":"stroke-U01","name":"새 신경학적 증상","track":"뇌질환(뇌경색·뇌출혈)","reason":"뇌경색과 뇌출혈은 증상만으로 구분하지 못한다. 임의로 아스피린을 주거나 호전을 기다리지 않는다.","scenario":"재활 중인 환자에게 갑자기 평소 없던 얼굴 비대칭과 말 어눌함이 생긴다.","focus":"뇌졸중 재발 가능성을 포함한 응급 변화","action":"즉시 병원 응급 호출을 하고 마지막 정상 확인 시각을 전달한다.","followup":"의료진에게 인계될 때까지 의식·호흡 변화와 발생 시각을 관찰한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U02","name":"삼킴 확인 전 경구 섭취","track":"뇌질환(뇌경색·뇌출혈)","reason":"급성 뇌졸중에서는 훈련된 의료인의 삼킴 선별이 경구 섭취보다 먼저다. 간병사가 물로 시험하지 않는다.","scenario":"급성 뇌졸중으로 입원했으나 삼킴 선별검사 여부가 확인되지 않은 환자가 물을 원한다.","focus":"흡인 위험과 삼킴 평가 필요성","action":"경구 음식·물·약을 주기 전 담당 의료진에게 삼킴 허용 여부를 확인한다.","followup":"금식·식이 질감·보조 방법의 최신 지시를 인계한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U03","name":"젖은 목소리","track":"뇌질환(뇌경색·뇌출혈)","reason":"기침과 목소리 변화는 재평가가 필요한 단서다. 걸쭉한 물로 임의 변경해 계속 먹이지 않는다.","scenario":"처방된 식사를 돕던 중 환자가 기침하고 목소리가 젖은 소리로 바뀐다.","focus":"식사 중 삼킴 안전성의 변화","action":"식사 보조를 중단하고 즉시 간호사를 부른다.","followup":"호흡 상태와 증상이 생긴 음식·시각·섭취량을 전달한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U04","name":"편마비 어깨 보호","track":"뇌질환(뇌경색·뇌출혈)","reason":"약해진 어깨는 당김에 취약하다. 체위와 이동 보조는 재활팀의 개인별 지시를 따른다.","scenario":"침대에서 일으킬 때 마비된 팔을 잡아당기면 환자가 어깨 통증을 호소한다.","focus":"마비측 관절 손상 위험","action":"팔을 당기지 않고 교육받은 체간 지지·이동 방법으로 도움을 요청한다.","followup":"이동 후 통증과 팔 지지 상태를 확인한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U05","name":"편측 무시","track":"뇌질환(뇌경색·뇌출혈)","reason":"편측 무시는 단순한 고집과 다르다. 훈련되지 않은 강제 운동 대신 안전한 환경과 반복 단서를 제공한다.","scenario":"환자가 왼쪽 접시의 음식을 남기고 이동할 때 왼쪽 문틀에 부딪힌다.","focus":"한쪽 공간을 탐색하지 못하는 기능 문제","action":"재활팀의 시선 탐색 지시에 따라 왼쪽을 확인하도록 단서를 준다.","followup":"충돌·남긴 음식 위치와 단서 제공 후 변화를 기록한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U06","name":"실어증과 선택권","track":"뇌질환(뇌경색·뇌출혈)","reason":"말을 못한다는 이유만으로 이해나 선호가 없다고 판단하지 않는다. 질문의 복잡성을 줄인다.","scenario":"말하기는 어렵지만 그림 두 장 중 원하는 것을 일관되게 가리키는 환자다.","focus":"언어 표현 장애와 의사결정 능력의 구분","action":"그림·예 아니오 질문을 사용하고 답할 시간을 준다.","followup":"환자가 사용한 의사표현 수단과 선택 내용을 기록한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U07","name":"재활 피로 조절","track":"뇌질환(뇌경색·뇌출혈)","reason":"무조건 쉬게 하거나 목표를 강요하는 대신 개별 계획과 상태를 조정한다.","scenario":"이동 연습 후 피로가 심해진 환자가 다음 활동을 쉬고 싶다고 한다. 새로운 마비나 호흡곤란은 없다.","focus":"활동 내성과 휴식의 균형","action":"재활 계획 안에서 휴식을 제공하고 지속되는 피로를 팀에 알린다.","followup":"활동 종류·시간·회복 소요와 피로 호소를 비교한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U08","name":"피부와 자세","track":"뇌질환(뇌경색·뇌출혈)","reason":"감각 저하는 불편 호소를 줄일 수 있다. 붉은 부위를 문지르거나 단계를 간병사가 확정하지 않는다.","scenario":"감각이 둔한 마비측 발꿈치가 침상에 오래 닿아 있고 붉은 변화가 보인다.","focus":"압박 손상 위험","action":"압박을 줄이는 허용된 자세를 돕고 피부 변화를 간호사에게 알린다.","followup":"제압 후 피부 색 변화와 재압박 여부를 점검한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U09","name":"항응고 치료 중 관찰","track":"뇌질환(뇌경색·뇌출혈)","reason":"출혈 여부와 약 조정은 의료진 판단이다. 검은 변의 원인을 약 때문이라고 단정하거나 복용을 독단적으로 중단하지 않는다.","scenario":"항응고제를 처방받은 환자에게 검은 변과 새 어지럼이 나타난다.","focus":"출혈 가능성을 시사하는 변화","action":"즉시 간호사에게 알리고 혼자 걷지 않도록 돕는다.","followup":"변의 양상·어지럼 시작·관찰한 다른 출혈 징후를 보고한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"stroke-U10","name":"퇴원 후 이동 계획","track":"뇌질환(뇌경색·뇌출혈)","reason":"병원에서 가능했던 이동이 가정에서도 안전한 것은 아니다. 실제 수행 가능한 계획이 필요하다.","scenario":"병실에서는 두 사람이 돕던 환자를 가족이 집에서 혼자 옮기려 한다.","focus":"돌봄 환경에 맞는 이동 보조 능력","action":"퇴원팀에 도움 인력과 이동 보조기 교육 필요를 전달한다.","followup":"가족의 시범 수행과 주거 동선·도움 인력 확보 여부를 확인한다.","source":"https://www.nice.org.uk/guidance/ng236/chapter/Recommendations"},{"id":"parkinson-U01","name":"복약 시각의 중요성","track":"파킨슨","reason":"파킨슨 치료약은 시간 준수가 중요하다. 간병사가 임의로 다음 회차와 합치거나 처방을 바꾸지 않는다.","scenario":"평소 정해진 시각에 복용하는 약이 식사 지연으로 늦어질 상황이다.","focus":"개인별 투약 일정의 유지","action":"담당 간호사에게 평소 복용 시각과 지연 우려를 바로 알린다.","followup":"실제 투약은 담당자가 확인하고 움직임 변화와 함께 인계한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U02","name":"약효 변동","track":"파킨슨","reason":"관찰 패턴은 의료진의 평가를 돕지만 약효 소진을 간병사가 확진하거나 용량을 늘리지 않는다.","scenario":"매일 다음 투약 직전에 움직임이 느려졌다가 투약 후 나아지는 양상이 반복된다.","focus":"약효와 연관될 수 있는 시간적 운동 변동","action":"복약 확인 시각과 운동 상태의 연관을 일지로 전달한다.","followup":"같은 활동에서 움직임이 달라지는 시간대를 비교한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U03","name":"보행 동결","track":"파킨슨","reason":"억지로 팔을 끌면 균형이 무너질 수 있다. 개인별 리듬·시각 단서의 적합성은 치료팀과 정한다.","scenario":"문턱 앞에서 발이 바닥에 붙은 듯 멈춘 환자가 급히 앞으로 기울어진다.","focus":"동결 시 낙상 위험","action":"안전을 확보하고 재활팀에게 배운 멈춤·단서 전략을 사용한다.","followup":"어떤 장소와 단서에서 동결이 줄거나 늘었는지 기록한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U04","name":"기립 시 어지럼","track":"파킨슨","reason":"갑작스러운 자세 변화는 낙상을 초래할 수 있다. 원인은 의료진이 평가하며 소금·수분 증량을 임의로 정하지 않는다.","scenario":"누웠다 일어난 직후 눈앞이 어둡다고 말한다.","focus":"자세 변화와 연관된 저혈압 가능성","action":"안전하게 앉거나 눕도록 돕고 간호사에게 증상을 보고한다.","followup":"일어선 시각·지속 시간·회복과 재발 여부를 인계한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U05","name":"불수의 운동","track":"파킨슨","reason":"떨림과 이상운동은 구분해 기술해야 한다. 간병사가 약을 끊어 시험하지 않는다.","scenario":"환자가 쉬고 있을 때 몸통과 팔이 의도와 다르게 크게 움직이기 시작했다.","focus":"새로운 이상운동의 관찰","action":"주변 충돌 위험을 줄이고 운동 양상과 시각을 보고한다.","followup":"동영상이 필요하면 별도 동의를 받고 기관 절차를 따른다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U06","name":"식사와 삼킴","track":"파킨슨","reason":"침 흘림이 단순한 위생 문제만은 아니다. 물을 더 주어 넘기게 하는 방법은 안전하지 않다.","scenario":"식사 시간이 길어지고 침을 흘리며 음식 뒤에 기침한다.","focus":"연하 안전성과 영양 저하 위험","action":"기침 시 식사를 멈추고 간호사에게 삼킴 재평가를 요청한다.","followup":"식이 지시가 갱신되면 보조 자세와 질감을 정확히 인계한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U07","name":"작은 목소리","track":"파킨슨","reason":"작은 목소리를 의욕 부족으로 해석하지 않는다. 언어치료팀과 의사소통 전략을 맞춘다.","scenario":"의식은 명료하지만 목소리가 작아 가족이 환자의 말을 자주 놓친다.","focus":"음성 저하와 의사표현 보조","action":"조용한 환경에서 가까이 듣고 필요하면 글·그림을 활용한다.","followup":"환자가 가장 편한 표현 방식과 듣기 어려운 상황을 공유한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U08","name":"환시 관찰","track":"파킨슨","reason":"약·수면·인지 변화 등 여러 원인이 가능하다. 환시 내용을 확정된 현실처럼 기록하지 않는다.","scenario":"환자가 없는 사람을 본다고 말하지만 주변에서는 보이지 않는다.","focus":"환시와 안전·불안의 평가 필요","action":"논쟁하지 않고 안전을 확보하며 새 증상과 불안을 간호사에게 알린다.","followup":"발생 시각·각성 수준·복약 변화 여부를 구분하여 보고한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U09","name":"충동 행동","track":"파킨슨","reason":"일부 치료에서 충동 조절 문제가 생길 수 있다. 보호자에게 숨기라고 하거나 간병사가 약을 끊지 않는다.","scenario":"최근 처방 변경 후 가족이 환자의 과도한 구매 행동을 걱정한다.","focus":"치료와 연관될 수 있는 행동 변화","action":"비난하지 않고 관찰 사실과 가족 우려를 진료팀에 전달한다.","followup":"지출·행동 변화는 개인정보를 보호하며 담당자에게만 공유한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"parkinson-U10","name":"변비와 생활 지원","track":"파킨슨","reason":"변비 관리는 복약·삼킴·수분 제한을 함께 고려한다. 임의 관장이나 하제 투여는 하지 않는다.","scenario":"활동량이 줄고 배변이 평소보다 어렵지만 심한 복통·구토는 없다.","focus":"배변 양상 변화와 개별 생활 계획","action":"허용된 활동·식이·수분 계획을 확인하고 배변 양상을 보고한다.","followup":"배변 간격·변 형태·복부 불편과 계획 후 반응을 기록한다.","source":"https://www.nice.org.uk/guidance/ng71/chapter/Recommendations"},{"id":"brain-cancer-U01","name":"원발과 전이의 구분","track":"뇌암","reason":"뇌의 악성 종양에는 원발과 전이가 포함된다. 간병사가 병리 진단을 재해석하지 않는다.","scenario":"환자가 폐암에서 뇌로 전이됐다는 설명을 들었으나 가족은 새로운 원발 뇌암이라고 이해한다.","focus":"원발 부위와 뇌 병변의 구분","action":"진료 설명을 다시 확인하도록 연결하고 확인된 진단 용어만 사용한다.","followup":"환자·가족의 질문과 의료진 설명을 구분해 기록한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U02","name":"급격한 의식 변화","track":"뇌암","reason":"뇌압 상승 등 여러 원인이 가능하지만 간병사는 원인 확정보다 안전과 신속한 보고를 우선한다.","scenario":"평소 깨우면 답하던 환자가 반복 구토 후 잘 깨지 않는다.","focus":"의식 저하를 동반한 신경학적 응급 변화","action":"즉시 응급 호출하고 경구 섭취를 주지 않는다.","followup":"마지막 정상 반응 시각·구토·호흡 변화를 전달한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U03","name":"발작 중 안전","track":"뇌암","reason":"발작 중 강제 억제와 입안 물건은 손상을 줄 수 있다. 기관 응급 절차와 교육 범위를 따른다.","scenario":"환자의 팔·다리가 갑자기 떨리고 반응이 없다.","focus":"발작 중 손상·기도 위험","action":"도움을 부르고 주변을 치우며 시간을 재되 억지로 누르거나 입에 물건을 넣지 않는다.","followup":"지속 시간·움직임·호흡과 회복 상태를 전달한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U04","name":"발작 후 관찰","track":"뇌암","reason":"발작이 끝났다고 즉시 식사나 보행이 안전한 것은 아니다. 재발이나 회복 지연을 확인한다.","scenario":"떨림은 멎었지만 환자가 졸리고 말에 바로 반응하지 않는다.","focus":"발작 후 회복과 지속 이상 감시","action":"곁에서 호흡·반응을 관찰하고 의료진에게 회복 양상을 알린다.","followup":"깨는 과정과 다시 발생한 움직임 여부를 기록한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U05","name":"새 편측 약화","track":"뇌암","reason":"피로로만 판단하면 신경학적 변화를 놓칠 수 있다. 낙상·화상 예방도 함께 고려한다.","scenario":"어제 잡던 컵을 오늘 오른손으로 반복해 떨어뜨린다.","focus":"새 운동 기능 저하","action":"발생 시각과 이전 수행 수준을 즉시 보고한다.","followup":"손 사용·보행의 안전을 확인하고 새 도움 수준을 인계한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U06","name":"시야와 충돌","track":"뇌암","reason":"시각 문제와 주의력 문제는 평가가 필요하다. 간병사가 시야 검사 결과를 진단으로 기록하지 않는다.","scenario":"환자가 같은 쪽 물건에 반복해 부딪히고 글의 일부를 놓친다.","focus":"시야·공간 인식 변화","action":"장애물을 줄이고 변화 양상을 담당자에게 알린다.","followup":"충돌 위치와 효과가 있었던 안전 단서를 공유한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U07","name":"행동과 인격 변화","track":"뇌암","reason":"도덕적 비난보다 변화의 원인을 평가해야 한다. 임의로 진정제를 주지 않는다.","scenario":"평소 온화하던 환자가 갑자기 화를 내고 충동적으로 일어나려 한다.","focus":"뇌 기능·약물·상태 변화에 대한 평가 필요","action":"안전을 확보하고 평소와 다른 행동을 구체적으로 보고한다.","followup":"시간대·유발 상황·위험 행동과 도움이 된 대응을 기록한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U08","name":"스테로이드 관련 관찰","track":"뇌암","reason":"부작용 여부와 용량 조정은 의료진이 판단한다. 간병사가 약을 급히 끊거나 감량하지 않는다.","scenario":"처방된 스테로이드를 복용하는 환자가 심한 갈증과 밤잠 변화를 호소한다.","focus":"치료 중 새 전신 증상","action":"확인된 약 정보와 증상을 간호사에게 전달한다.","followup":"섭취·수면·각성 상태의 경과를 살핀다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U09","name":"인지 피로와 안내","track":"뇌암","reason":"병변·치료·피로에 따라 처리 속도가 달라질 수 있다. 능력을 과소평가하거나 재촉하지 않는다.","scenario":"긴 설명에는 집중하지 못하지만 한 단계씩 말하면 세수를 수행한다.","focus":"인지 부담을 줄이는 활동 지원","action":"짧은 안내와 휴식으로 남은 수행 능력을 돕는다.","followup":"가능했던 도움 수준과 피로가 커진 조건을 인계한다.","source":"https://www.cancer.gov/types/brain"},{"id":"brain-cancer-U10","name":"가정 응급 계획","track":"뇌암","reason":"간병사는 독자적인 응급약 처방을 만들지 않는다. 교육받은 내용과 실제 수행 가능성을 확인한다.","scenario":"퇴원을 앞둔 가족이 발작이 오면 누구에게 연락할지 모른다.","focus":"퇴원 후 신경학적 응급 대응 준비","action":"의료진이 정한 발작·의식 변화 대응 계획과 연락처 교육을 요청한다.","followup":"가족이 연락·안전 조치를 설명하고 시범 보이도록 돕는다.","source":"https://www.cancer.gov/types/brain"},{"id":"N-01","name":"우울의 일상 관찰","track":"정신건강·우울","reason":"우울은 정상 노화로 치부하지 않는다. 간병사가 진단하지 않고 평가·치료 참여를 지원한다.","scenario":"2주 이상 흥미가 줄고 잠·식사 패턴이 달라졌다.","focus":"지속되는 기분·기능 변화","action":"의욕 부족을 탓하지 않고 기간과 생활 영향을 보고한다.","followup":"수면·식사·활동의 변화를 확인한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-02","name":"자해 위험 대응","track":"정신건강·우울","reason":"직접적인 위험 표현은 비밀 약속보다 안전 확보가 우선이다. 위험 물건 접근은 안전하게 제한하고 기관 절차를 따른다.","scenario":"환자가 죽고 싶고 구체적인 방법도 생각했다고 말한다.","focus":"즉각적인 자해 위험","action":"혼자 두지 않고 안전을 확보하며 즉시 의료진·응급 도움을 요청한다.","followup":"전문 담당자에게 직접 인계했는지 확인한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-03","name":"불안과 신체 증상","track":"정신건강·우울","reason":"불안·공황과 심폐질환 증상은 겹칠 수 있다. 이전 불안 병력만으로 응급 평가를 미루지 않는다.","scenario":"갑자기 숨차고 가슴이 답답하다고 호소한다.","focus":"불안으로 단정할 수 없는 급성 신체 변화","action":"즉시 상태를 알리고 편안한 자세로 곁을 지킨다.","followup":"호흡·통증·반응의 변화와 평가 결과를 인계한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-04","name":"정신증·망상과 대화","track":"정신건강·우울","reason":"안전한 관계와 비위협적 의사소통이 중요하다. 급성 변화라면 섬망·약물 등도 평가해야 한다.","scenario":"음식에 독이 있다고 두려워하며 먹지 않는다.","focus":"두려움과 섭취 저하","action":"망상을 맞다고 강화하거나 논쟁하지 않고 불안을 인정해 담당자에게 알린다.","followup":"섭취·불안·안전 상태를 확인한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-05","name":"조증 의심 변화","track":"정신건강·우울","reason":"활발함으로만 보지 않고 평소 대비 변화와 기능 손상을 살핀다. 강압적 논쟁을 피한다.","scenario":"거의 자지 않고 과도하게 말하며 무리한 지출을 하려 한다.","focus":"수면 감소·활동 증가·충동성","action":"자극을 줄이고 위험 행동을 관찰해 평가를 요청한다.","followup":"수면과 위험 행동에 대한 팀 계획을 확인한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-06","name":"불면과 돌봄 환경","track":"정신건강·우울","reason":"수면 문제에는 환경·통증·약물·질환 요인이 함께 있을 수 있다.","scenario":"밤마다 깨어나고 낮에 졸아 이동 중 비틀거린다.","focus":"수면 리듬과 낙상 위험","action":"소음·빛·통증을 살피고 수면제 임의 추가 없이 보고한다.","followup":"수면 기록과 낮 각성·보행 변화를 인계한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-07","name":"정신과 약물 안전","track":"정신건강·우울","reason":"부작용 관찰은 복약 지원의 일부다. 약을 임의 중단하거나 다른 환자 약을 주지 않는다.","scenario":"약 변경 뒤 심한 졸림과 일어설 때 어지럼이 생겼다.","focus":"투약 변경 후 각성·자세 변화","action":"이동을 안전하게 돕고 약 변경 시점과 증상을 보고한다.","followup":"처방 확인과 이후 낙상·각성 상태를 기록한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-08","name":"알코올 중단 후 변화","track":"정신건강·우울","reason":"급성 금단은 전문 평가가 필요하다. 간병사가 술이나 진정제를 제공하지 않는다.","scenario":"입원 후 갑자기 떨림·초조·혼돈이 발생했다.","focus":"금단 가능성을 포함한 급성 변화","action":"즉시 의료진을 호출하고 알고 있는 음주·중단 정보를 전달한다.","followup":"의식·행동 변화와 관찰 지시를 인계한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-09","name":"외상 경험과 돌봄 거부","track":"정신건강·우울","reason":"거부를 비협조로 단정하지 않는다. 존중·예측 가능한 절차가 안전감을 돕는다.","scenario":"예고 없이 몸을 만지면 놀라며 밀쳐낸다.","focus":"안전감·동의와 외상 관련 반응","action":"접촉 전 설명하고 허락을 구하며 환자가 통제할 선택지를 준다.","followup":"수용 가능한 접촉·설명 방식을 기록한다.","source":"https://www.nimh.nih.gov/health/topics/depression"},{"id":"N-10","name":"신경질환과 정신건강 통합","track":"정신건강·우울","reason":"신경질환 뒤 우울이 동반될 수 있다. 신체 재활과 정신건강 지원을 연결한다.","scenario":"뇌졸중 후 재활을 거부하며 자신이 짐이라고 말한다.","focus":"기능 상실·우울·안전 문제","action":"감정을 듣고 재활팀에 기분 변화와 환자의 목표를 전달한다.","followup":"작은 활동 목표와 안전 평가 후 계획을 확인한다.","source":"https://www.nimh.nih.gov/health/topics/depression"}]},{"id":"digestive","title":"소화기질환 전문간병사","category":"질환군 교육","scope":"위·장·간·췌장 질환과 위암·대장암·간암·췌장암 심화, 영양·배변·장루 돌봄","tracks":["소화기 공통","위암","대장암","간암","췌장암"],"units":[{"id":"digestive-E1","name":"위장관 기능","track":"소화기 공통","reason":"식이 중단·진행은 원인과 상태에 따라 다르다. 간병사가 일률적 금식을 결정하지 않는다.","scenario":"환자가 속이 불편하면 원인과 관계없이 금식해야 한다고 생각한다.","focus":"증상·진단별 식이 계획의 구분","action":"통증·섭취 상태를 보고하고 현재 식이 지시를 확인한다.","followup":"섭취·배변·불편 변화를 기록한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E2","name":"위장관 출혈","track":"소화기 공통","reason":"약·음식 등 원인도 가능하지만 증상을 동반한 새 변화는 평가가 필요하다.","scenario":"검은 변과 새 어지럼을 함께 호소한다.","focus":"출혈 가능성을 포함한 급성 변화","action":"즉시 의료진에게 알리고 낙상을 예방한다.","followup":"관찰한 변 양상·시각·의식 변화를 전달한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E3","name":"지속 복통","track":"소화기 공통","reason":"원인을 소화불량으로 단정하지 않는다.","scenario":"복통이 점점 심해지고 반복 구토가 동반된다.","focus":"응급 복부 질환 가능성","action":"즉시 담당자에게 알려 평가를 받고 임의 약·마사지로 지연시키지 않는다.","followup":"통증 위치·시각·구토·마지막 섭취를 인계한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E4","name":"역류와 생활 지원","track":"소화기 공통","reason":"모든 가슴 불편을 역류로 확정하지 않는다. 새 심한 흉통·호흡곤란은 즉시 보고한다.","scenario":"누운 뒤 신물이 올라오고 불편하다고 한다.","focus":"자세·식사와 연관된 증상","action":"증상을 보고하고 개별 식사·자세 계획을 확인한다.","followup":"증상 조건과 허용 자세 후 변화를 살핀다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E5","name":"설사와 탈수","track":"소화기 공통","reason":"감염·약물 등 원인은 다양하다. 임의 지사제와 무제한 수분을 적용하지 않는다.","scenario":"묽은 변이 반복되고 어지러우며 소변이 줄었다고 한다.","focus":"체액 손실과 원인 평가","action":"횟수·섭취·전신 변화를 보고하고 수분 지시를 확인한다.","followup":"확인된 배출·섭취와 대응을 기록한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E6","name":"감염성 설사 의심","track":"소화기 공통","reason":"원인균을 외관으로 확정하지 않는다. 환자별 환경·오염물 관리가 중요하다.","scenario":"병동에서 새 설사 환자가 생겨 감염관리 지침을 확인해야 한다.","focus":"배설물·환경을 통한 감염 예방","action":"기관의 손 위생·보호구·화장실·물품 지침을 따른다.","followup":"증상·접촉 우려를 담당자에게 전달한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E7","name":"변비와 위험 신호","track":"소화기 공통","reason":"단순 변비로만 판단하면 위험한 변화를 놓칠 수 있다.","scenario":"며칠 배변이 없고 새 심한 복통·구토가 생겼다.","focus":"폐색 등을 포함한 평가 필요","action":"즉시 의료진에게 알리고 임의 관장·하제를 사용하지 않는다.","followup":"마지막 배변·가스·구토 시각을 기록한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E8","name":"간질환의 일상","track":"소화기 공통","reason":"일률적 제한은 영양 저하를 악화시킬 수 있다. 간병사가 식단을 처방하지 않는다.","scenario":"간질환 환자에게 가족이 모든 단백질을 끊으려 한다.","focus":"개별 영양 상태와 간기능을 고려한 식이","action":"영양·진료팀의 개인별 식단을 확인하도록 돕는다.","followup":"실제 섭취와 기능·체중 변화를 전달한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E9","name":"담도·췌장 증상","track":"소화기 공통","reason":"원인 확정이나 약 선택은 의료진 영역이다. 소화제만 주며 기다리지 않는다.","scenario":"윗배 통증과 황달·오한이 새로 나타났다.","focus":"담도·췌장 질환 등을 포함한 긴급 변화","action":"즉시 의료진에게 증상과 시작 시각을 알린다.","followup":"의식·통증·확인된 체온과 대응을 인계한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"digestive-E10","name":"장질환과 존엄","track":"소화기 공통","reason":"증상 관리뿐 아니라 사생활과 선택권도 중요하다.","scenario":"배변 급박감 때문에 환자가 외출·면회를 포기하려 한다.","focus":"배변 지원과 사회적 불안","action":"환자 선호를 듣고 화장실 접근·피부 관리·상담을 조율한다.","followup":"도움이 된 환경과 미해결 불편을 기록한다.","source":"https://www.niddk.nih.gov/health-information/digestive-diseases"},{"id":"gastric-U01","name":"수술 범위와 식이","track":"위암","reason":"절제 범위와 회복에 따라 식이 계획이 다르다. 같은 병실의 식사를 기준으로 바꾸지 않는다.","scenario":"위 절제 수술을 받은 환자가 옆 환자와 같은 양의 일반식을 원한다.","focus":"수술별 식이 진행 계획","action":"본인의 수술 후 식이 단계와 허용량을 먼저 확인한다.","followup":"실제 먹은 양과 불편을 식이 담당자에게 전달한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U02","name":"조기 포만","track":"위암","reason":"무조건 완식을 요구하면 불편이 커질 수 있다. 환자별 섭취 목표와 체중 경과를 함께 본다.","scenario":"몇 숟가락 먹은 뒤 배부르다고 하고 더 먹으면 불편하다.","focus":"섭취 용량 감소와 영양 지원","action":"영양팀이 정한 소량·분할 식사 계획을 돕는다.","followup":"식사 횟수·실제량·포만감과 체중 추이를 기록한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U03","name":"식후 조기 증상","track":"위암","reason":"덤핑 등 가능성이 있지만 스스로 확진하지 않는다. 식이 변경은 영양·진료팀과 정한다.","scenario":"식후 얼마 지나지 않아 두근거림·복부 불편·어지럼이 반복된다.","focus":"식후 시간과 연관된 증상 평가","action":"안전을 확보하고 식사 내용·증상 시각을 간호사에게 알린다.","followup":"증상 발생까지의 시간과 회복·재발을 기록한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U04","name":"식후 지연 증상","track":"위암","reason":"증상만으로 혈당을 추정할 수 없다. 의식이 떨어지면 입으로 먹이지 않는다.","scenario":"식사 몇 시간 뒤 식은땀과 떨림이 나타나고 힘이 빠진다.","focus":"저혈당 등을 포함한 지연성 식후 변화","action":"즉시 담당자에게 알리고 기관의 혈당·응급 대응 절차를 따른다.","followup":"식사 시각·내용·확인된 측정값과 대응을 구분해 인계한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U05","name":"수술 후 출혈","track":"위암","reason":"검은 변의 원인은 여러 가지지만 어지럼을 동반한 새 변화는 평가가 필요하다.","scenario":"수술 후 검은 변과 어지럼을 새로 호소한다.","focus":"위장관 출혈 가능성","action":"즉시 간호사에게 보고하고 안전한 이동을 돕는다.","followup":"변의 색·횟수·시각과 어지럼 경과를 전달한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U06","name":"지속 구토와 복통","track":"위암","reason":"소화가 덜 됐다고만 판단하지 않는다. 복부 마사지나 임의 약물로 지연시키지 않는다.","scenario":"수술 후 구토가 반복되고 복통이 점차 심해진다.","focus":"수술 후 통과 장애·합병증 가능성","action":"경구 섭취를 강요하지 않고 즉시 의료진에게 알린다.","followup":"구토량은 측정·추정을 구분하고 마지막 배변·섭취를 기록한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U07","name":"장기 영양 추적","track":"위암","reason":"위 절제 후 철분·비타민 등 관리가 필요할 수 있다. 보충제 종류·용량은 의료진이 정한다.","scenario":"수술 후 외래 영양검사를 더 이상 받을 필요가 없다고 생각하는 환자다.","focus":"장기 영양 결핍 추적의 필요성","action":"퇴원 계획의 영양·혈액검사 일정과 상담을 확인하도록 돕는다.","followup":"예약과 처방 이해 여부를 환자의 설명으로 확인한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U08","name":"경관영양 관 보호","track":"위암","reason":"관 위치와 재사용 가능 여부는 의료진이 확인한다. 밀어 넣거나 물로 시험하지 않는다.","scenario":"영양관이 평소보다 바깥으로 길게 나와 보인다.","focus":"관 이탈 가능성","action":"관 사용을 진행하지 않고 간호사에게 즉시 알린다.","followup":"발견 시각·당김 상황·환자 불편을 인계한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U09","name":"식사와 체중 기록","track":"위암","reason":"주관적 표현만으로 영양 상태를 평가하기 어렵다. 추정치에는 추정임을 표시한다.","scenario":"가족은 많이 먹었다고 말하지만 기록에는 실제 섭취량이 없다.","focus":"영양 관찰의 구체성","action":"제공량과 실제 섭취량을 구분해 정해진 방식으로 기록한다.","followup":"같은 조건의 체중과 식사 후 불편을 함께 전달한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"gastric-U10","name":"퇴원 후 식생활","track":"위암","reason":"일률적 금지 목록보다 개인 반응과 영양 균형을 고려한다. 치료 효과를 보장하는 식품을 권하지 않는다.","scenario":"환자가 집에서 먹던 음식을 전부 금지해야 하는지 걱정한다.","focus":"지속 가능한 개별 식이 교육","action":"영양사와 허용 음식·분량·불편 시 대응을 확인한다.","followup":"환자가 실제 식단 예를 말해 보도록 하여 이해를 확인한다.","source":"https://www.cancer.gov/types/stomach"},{"id":"colorectal-U01","name":"장루 종류 확인","track":"대장암","reason":"장루 종류에 따라 배출물과 탈수 위험이 다르다. 모양만 보고 종류와 관리법을 정하지 않는다.","scenario":"환자가 장루 주머니를 가지고 있으나 회장루인지 결장루인지 인계되지 않았다.","focus":"장루 종류에 따른 돌봄 계획 확인","action":"간호사에게 장루 종류와 배출·피부 관리 계획을 확인한다.","followup":"확인된 장루 정보와 허용된 보조 범위를 인계한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U02","name":"장루 색 변화","track":"대장암","reason":"허혈 등 원인 평가는 의료진 몫이다. 마사지하거나 기구로 자극해 색을 바꾸려 하지 않는다.","scenario":"평소 붉고 촉촉하던 장루가 갑자기 검붉고 어두워 보인다.","focus":"장루 혈류 이상 가능성","action":"색 변화를 즉시 장루 담당 간호사에게 알린다.","followup":"변화 시각과 통증·배출 변화 여부를 전달한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U03","name":"누출과 피부","track":"대장암","reason":"누출을 테이프로 계속 덮으면 피부 노출이 지속될 수 있다. 제품 선택은 전문 인력과 조정한다.","scenario":"주머니 가장자리로 배출물이 새고 피부가 따갑다고 한다.","focus":"장루 주변 피부 손상 위험","action":"담당자에게 누출을 알리고 교육받은 피부 보호·교환 보조를 따른다.","followup":"교환 후 누출·통증·피부 변화의 경과를 확인한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U04","name":"배출 증가와 탈수","track":"대장암","reason":"일률적인 음료 증량이나 지사제 사용 대신 개별 평가가 필요하다. 양은 측정한 범위에서 제공한다.","scenario":"회장루 배출이 평소보다 많고 묽으며 어지럽고 소변이 줄었다고 한다.","focus":"체액·전해질 손실 위험","action":"배출 변화와 어지럼·소변 감소를 신속히 보고한다.","followup":"배출량·섭취량·소변 관찰과 의료진 지시를 인계한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U05","name":"폐색 의심","track":"대장암","reason":"장루에 물건을 넣거나 임의 관장·하제로 해결하지 않는다. 원인과 처치는 의료진이 정한다.","scenario":"복부가 팽팽해지고 구토하며 평소 나오던 가스와 배출물이 나오지 않는다.","focus":"장폐색 등을 포함한 긴급 변화","action":"억지로 먹이지 않고 즉시 의료진에게 알린다.","followup":"마지막 배출·구토 시각과 복부 불편을 전달한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U06","name":"수술 후 악화","track":"대장암","reason":"수술 후에는 아픈 것이 당연하다고 넘기지 않는다. 상처·복부 합병증 여부는 전문 평가가 필요하다.","scenario":"대장 수술 후 통증이 점점 커지고 열감과 오한을 호소한다.","focus":"수술 후 합병증 가능성","action":"새로운 통증과 전신 변화를 즉시 보고한다.","followup":"증상 시작·강도·활동 영향과 확인된 체온을 기록한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U07","name":"직장 수술 후 배변","track":"대장암","reason":"회복 경과는 개인차가 있다. 모든 설사로 단정해 임의 지사제를 주지 않는다.","scenario":"수술 후 배변 횟수가 늘고 갑자기 참기 어렵다고 한다.","focus":"수술 후 배변 기능 변화","action":"빈도·급박감·생활 영향을 기록해 진료팀과 계획을 확인한다.","followup":"식사·배변 시간과 피부 불편을 함께 관찰한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U08","name":"신경병증과 낙상","track":"대장암","reason":"신경병증은 안전에 영향을 준다. 뜨거운 물로 발을 담가 감각을 시험하지 않는다.","scenario":"항암치료 후 발이 저려 슬리퍼가 벗겨진 것도 잘 못 느낀다.","focus":"감각 저하와 이동 손상 위험","action":"발 보호와 안전한 보행을 돕고 새 감각 변화를 보고한다.","followup":"넘어질 뻔한 상황과 보조기·신발 사용 상태를 확인한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U09","name":"장루와 신체상","track":"대장암","reason":"기능 관리뿐 아니라 존엄과 사회적 참여도 중요하다. 동의 없이 장루를 가족에게 보여주지 않는다.","scenario":"환자가 냄새가 날까 걱정하며 가족 면회를 피한다.","focus":"신체상·사회적 불안과 사생활","action":"감정을 듣고 장루 담당자와 실용적인 관리·상담을 연결한다.","followup":"환자가 선택한 면회 방식과 필요한 지원을 인계한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"colorectal-U10","name":"독립 관리 준비","track":"대장암","reason":"설명을 들은 것과 수행 가능한 것은 다르다. 시력·손 기능·환경을 함께 확인한다.","scenario":"퇴원을 앞둔 환자가 주머니를 비우는 순서를 말하지만 실제 수행은 해보지 않았다.","focus":"자가 관리의 실제 수행 확인","action":"간호사 지도 아래 환자가 가능한 단계를 직접 해보도록 돕는다.","followup":"도움이 필요한 단계와 보급품·연락처를 기록한다.","source":"https://www.cancer.gov/types/colorectal"},{"id":"liver-U01","name":"간암과 간기능","track":"간암","reason":"간암 진단만으로 간기능이나 돌봄 수준을 정할 수 없다. 동반 간질환도 중요하다.","scenario":"같은 간암 환자라도 한 사람은 복수가 있고 다른 사람은 일상 활동이 가능하다.","focus":"암과 기저 간기능을 함께 고려한 돌봄","action":"각 환자의 활동·식이·증상 계획을 별도로 확인한다.","followup":"진료팀이 설명한 주요 위험과 기능 수준을 인계한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U02","name":"복부 팽만","track":"간암","reason":"복수 배액·이뇨제·수분 제한은 의료진 계획이다. 간병사가 처치를 결정하지 않는다.","scenario":"복부가 평소보다 팽팽하고 누우면 숨차다고 한다.","focus":"복수 등을 포함한 체액·호흡 변화","action":"새 팽만과 숨참을 신속히 보고하고 편한 허용 자세를 돕는다.","followup":"측정 지시가 있으면 같은 조건의 체중·복부 둘레와 증상을 기록한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U03","name":"급성 혼돈","track":"간암","reason":"간성뇌증을 외관으로 확진하지 않는다. 감염·약물 등 다른 원인도 평가가 필요하다.","scenario":"평소 대화하던 환자가 낮에 몹시 졸리고 날짜를 혼동한다.","focus":"간성뇌증 등을 포함한 급성 의식 변화","action":"변화 시각과 평소 반응을 즉시 보고한다.","followup":"반응·낙상 위험·섭취와 배변 변화를 확인된 범위에서 전달한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U04","name":"토혈","track":"간암","reason":"출혈 위치를 단정하거나 음식으로 기운을 보충하려 하지 않는다. 청소보다 응급 대응이 먼저다.","scenario":"갑자기 피를 토하고 창백해 보인다.","focus":"위장관 출혈과 순환 악화 위험","action":"즉시 응급 호출하고 교육받은 기도·안전 보조를 한다.","followup":"시각·색·대략의 양·의식과 호흡 변화를 인계한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U05","name":"황달과 가려움","track":"간암","reason":"가려움을 참으라고만 하지 않는다. 약물·외용제 선택은 의료진에게 확인한다.","scenario":"황달이 심해 보이고 가려워 피부를 긁어 상처가 생긴다.","focus":"피부 손상 예방과 황달 변화 보고","action":"변화를 알리고 허용된 보습·손톱·침구 관리로 마찰을 줄인다.","followup":"피부 상처·수면 방해·관리 후 불편 변화를 기록한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U06","name":"복수 환자의 발열","track":"간암","reason":"원래 배가 불편한 환자라며 미루지 않는다. 복부 마사지나 임의 진통제로 지연시키지 않는다.","scenario":"복수가 있는 환자에게 새 복통과 오한이 발생했다.","focus":"감염 등을 포함한 긴급 복부 변화","action":"즉시 의료진에게 복통·오한·시작 시각을 보고한다.","followup":"의식·호흡·확인된 체온과 통증 경과를 전달한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U07","name":"배변 계획과 약","track":"간암","reason":"약 조절에 참고할 관찰 정보가 필요하지만 간병사가 목표 횟수나 용량을 정하지 않는다.","scenario":"의료진이 배변 관찰을 요청했으나 횟수만 있고 변 상태는 기록되지 않았다.","focus":"처방 목표에 필요한 배변 정보","action":"실제 횟수·상태·복부 불편을 정해진 방식으로 기록한다.","followup":"과도한 설사·어지럼 등 새 변화는 담당자에게 알린다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U08","name":"영양과 근감소","track":"간암","reason":"간질환이라는 이유로 일률적인 영양 제한을 하지 않는다. 상태와 치료 목표를 반영해야 한다.","scenario":"근육이 줄고 기운이 없는 환자에게 가족이 단백질을 모두 끊으려 한다.","focus":"개별 영양 처방의 필요","action":"영양팀에 식단을 확인하도록 돕고 임의 제한을 피한다.","followup":"실제 섭취·체중·기능 변화를 전달한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U09","name":"시술 후 천자 부위","track":"간암","reason":"시술별 안정·압박 지시가 다르다. 관찰과 의료진 대응을 구분한다.","scenario":"치료 시술 후 천자 부위가 부풀고 통증이 새로 심해진다.","focus":"시술 부위 출혈·합병증 가능성","action":"부위를 임의로 누르거나 걷게 하지 않고 즉시 담당자에게 알린다.","followup":"부종 발생·드레싱 변화·통증과 조치를 인계한다.","source":"https://www.cancer.gov/types/liver"},{"id":"liver-U10","name":"보완요법 상담","track":"간암","reason":"천연이라는 이유로 안전하거나 항암 효과가 보장되지 않는다. 치료팀과 정보 공유가 필요하다.","scenario":"가족이 간에 좋다는 달인 약을 가져와 몰래 먹이려 한다.","focus":"간기능·치료와 보충제품의 안전 확인","action":"제품 정보와 복용 의사를 진료팀에 먼저 확인하도록 안내한다.","followup":"확인된 복용 여부와 환자 의사를 기록한다.","source":"https://www.cancer.gov/types/liver"},{"id":"pancreatic-U01","name":"질환과 개인차","track":"췌장암","reason":"병기·치료·동반질환에 따라 돌봄 요구가 다르다. 진단명만으로 남은 수명이나 간병 난도를 단정하지 않는다.","scenario":"같은 췌장암 진단을 받은 두 환자의 식사량과 통증 정도가 크게 다르다.","focus":"진단명보다 개별 증상·기능에 근거한 돌봄","action":"각 환자의 증상과 허용된 활동·식이 계획을 따로 확인한다.","followup":"개별 목표와 선호를 인계표에 반영한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U02","name":"황달과 오한","track":"췌장암","reason":"스텐트가 있다는 이유로 배액이 항상 정상이라고 볼 수 없다. 막힘·감염의 진단은 의료진이 한다.","scenario":"피부가 더 노래지고 오한이 생겼으며 담도 스텐트 치료 이력이 있다.","focus":"담도 관련 합병증을 포함한 급성 변화","action":"황달 변화와 오한을 즉시 의료진에게 보고한다.","followup":"소변·대변 색 변화와 증상 시작 시각도 확인된 범위에서 전달한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U03","name":"지방변과 체중","track":"췌장암","reason":"췌장 기능 저하가 관련될 수 있지만 눈으로 확진하지 않는다. 효소제의 용량·투여법은 처방팀이 정한다.","scenario":"기름져 보이는 변이 반복되고 식사량에 비해 체중이 줄었다고 한다.","focus":"소화·흡수 저하 가능성과 영양 평가","action":"변 양상과 실제 섭취·체중 경과를 간호사와 영양팀에 전달한다.","followup":"처방된 식사·약 계획 시행 후 변과 섭취 변화를 살핀다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U04","name":"지속 구토","track":"췌장암","reason":"폐색·치료 부작용 등 원인은 평가가 필요하다. 스텐트 위치를 간병사가 추정해 해결하지 않는다.","scenario":"식후 구토가 반복되며 평소 먹던 음식도 넘기기 어렵다고 한다.","focus":"위장관 통과 장애를 포함한 섭취 문제","action":"억지로 먹이지 않고 구토와 섭취 곤란을 즉시 보고한다.","followup":"구토 시각·내용·횟수·마지막 섭취와 호흡 변화를 기록한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U05","name":"출혈 관찰","track":"췌장암","reason":"출혈 원인이나 고인 기간은 외형으로 확정하지 못한다. 뒷정리보다 도움 요청과 안전이 먼저다.","scenario":"환자가 피 섞인 구토를 하고 어지러워한다.","focus":"출혈과 흡인·순환 악화 위험","action":"즉시 응급 호출하고 교육받은 기도 보호·안전 보조를 시행한다.","followup":"관찰된 색·대략의 양과 의식·호흡 변화를 기록하되 측정과 추정을 구분한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U06","name":"복부·등 통증","track":"췌장암","reason":"통증은 환자의 보고를 존중한다. 치료약 증량이나 원인 확정은 간병사의 역할이 아니다.","scenario":"평소보다 등으로 퍼지는 통증이 커져 잠을 못 잔다고 말한다.","focus":"통증 양상 변화와 기능 영향","action":"환자가 표현한 강도·위치·수면 영향을 간호사에게 전달한다.","followup":"의료진 대응 후 같은 척도로 통증·각성·일상 기능을 재확인한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U07","name":"혈당 관련 증상","track":"췌장암","reason":"원인을 임의로 확정하지 않는다. 혈당 확인과 치료는 담당자의 절차에 따른다.","scenario":"식사를 거의 못 한 환자가 식은땀을 흘리고 반응이 둔해진다.","focus":"저혈당 등을 포함한 급성 의식 변화","action":"즉시 간호사를 호출하고 의식 저하 상태에 경구 음식을 주지 않는다.","followup":"최근 식사·확인된 투약·증상 시각을 전달한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U08","name":"혈전 의심 변화","track":"췌장암","reason":"한쪽 부종만으로 진단할 수 없지만 원인 평가 전 강한 마사지는 피한다.","scenario":"한쪽 종아리가 새로 붓고 아프다고 한다.","focus":"혈전 등을 포함한 한쪽 다리 변화","action":"마사지하지 않고 새 부종·통증을 신속히 보고한다.","followup":"새 호흡곤란·가슴 통증이 동반되면 즉시 응급 호출한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U09","name":"식욕 저하와 선택권","track":"췌장암","reason":"섭취 저하는 의지 부족만으로 설명되지 않는다. 강요보다 증상 관리와 목표 공유가 필요하다.","scenario":"소량만 먹고 지치는 환자에게 가족이 완식해야 한다며 권한다.","focus":"영양 목표와 환자 부담의 조정","action":"환자의 불편을 듣고 영양·완화돌봄팀과 가능한 식사 목표를 조율한다.","followup":"환자가 받아들인 음식·양·불편과 가족의 우려를 함께 인계한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"},{"id":"pancreatic-U10","name":"지역병원 전원","track":"췌장암","reason":"전원은 치료 포기와 동의어가 아니다. 이전 지시가 새 병원에서도 그대로 유효한지는 확인한다.","scenario":"집 가까운 병원으로 옮기는 환자에게 이전 통증·출혈 기록이 따로 보관되어 있다.","focus":"증상 관리 정보의 연속성","action":"동의와 기관 절차에 따라 최근 변화·계획·연락처를 인계한다.","followup":"도착 후 담당자와 새 돌봄·응급 보고 계획을 확인한다.","source":"https://www.cancer.gov/types/pancreatic/treatment"}]},{"id":"renal","title":"신장·비뇨기계질환 전문간병사","category":"질환군 교육","scope":"만성 신장질환·혈액투석·복막투석·이식·요실금·요폐·전립선비대·요로감염·혈뇨·요로결석·신경인성 방광","tracks":["신장질환 공통","투석","비뇨기계"],"units":[{"id":"renal-E1","name":"신장 기능 이해","track":"신장질환 공통","reason":"신장 기능은 노폐물·체액·전해질 조절 등 전신 상태와 관련된다. 소변 유무만으로 기능을 판단하지 않는다.","scenario":"환자가 신장은 소변만 만드는 장기라며 혈압·영양 검사를 불필요하게 여긴다.","focus":"체액·전해질·전신 상태와 신장 기능의 관계","action":"본인의 추적 검사와 돌봄 계획을 의료진에게 확인하도록 돕는다.","followup":"검사 일정과 환자가 이해한 관리 목표를 확인한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E2","name":"급성 소변량 변화","track":"신장질환 공통","reason":"섭취·배액·약물 등 다양한 원인이 가능하다. 물을 무조건 늘리거나 관을 조작하지 않는다.","scenario":"평소보다 소변이 갑자기 줄고 기운이 없다고 한다.","focus":"급성 신기능·배액 이상 등을 포함한 변화","action":"실제 관찰한 소변과 전신 변화를 신속히 보고한다.","followup":"확인된 섭취·배출·시각과 증상 경과를 기록한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E3","name":"부종의 관찰","track":"신장질환 공통","reason":"부종 원인을 간병사가 확정하지 않는다. 이뇨제나 압박 강도를 임의로 정하지 않는다.","scenario":"다리 붓기가 새로 심해지고 신발이 맞지 않는다.","focus":"체액 변화와 피부·이동 위험","action":"부종의 시작·범위·호흡 변화를 담당자에게 알린다.","followup":"같은 조건의 체중과 처방된 관찰을 지원한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E4","name":"만성 신장질환과 약","track":"신장질환 공통","reason":"일부 약은 신장 상태에 따라 주의가 필요하다. 일반 판매 약도 임의로 권하지 않는다.","scenario":"환자가 허리가 아프다며 평소 사 둔 진통제를 먹으려 한다.","focus":"신장 상태를 고려한 약물 안전","action":"제품명과 복용 의사를 약사·진료팀에 확인하도록 연결한다.","followup":"확인받은 복약 계획과 실제 복용 여부를 인계한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E5","name":"식이의 개인차","track":"신장질환 공통","reason":"투석 여부와 영양 상태 등에 따라 계획이 다르다. 단백질·칼륨 등을 일률적으로 제한하지 않는다.","scenario":"환자가 신장병 식단은 누구나 같다고 생각한다.","focus":"단계·치료·검사에 따른 영양 계획","action":"영양팀의 개인별 식이·수분 지시를 확인한다.","followup":"환자가 먹는 실제 음식과 교육 이해를 확인한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E6","name":"검사값 해석의 한계","track":"신장질환 공통","reason":"전해질 이상은 검사와 임상 평가가 필요하다. 음식·약으로 시험하여 진단하지 않는다.","scenario":"환자가 피곤하니 칼륨이 높다고 간병사에게 판단해 달라고 한다.","focus":"증상만으로 전해질 이상을 확정할 수 없음","action":"불편을 보고하고 검사 해석은 의료진에게 확인하도록 돕는다.","followup":"새 근력 저하·두근거림 등 변화와 보고 시각을 남긴다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E7","name":"혈뇨와 통증","track":"신장질환 공통","reason":"신장병의 당연한 증상으로 넘기지 않는다. 원인 진단과 처치는 의료진 영역이다.","scenario":"소변에 선명한 피가 보이고 옆구리가 아프다고 한다.","focus":"출혈·요로 문제 등을 포함한 새 변화","action":"시각·색·통증을 신속히 간호사에게 보고한다.","followup":"배뇨 양상·발열·상태 변화를 관찰한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E8","name":"신장질환의 피로","track":"신장질환 공통","reason":"빈혈·수면·치료 등 원인은 평가가 필요하다. 무조건 운동을 금지하거나 강요하지 않는다.","scenario":"일상 활동을 하면 쉽게 지치지만 갑작스러운 숨참은 없다.","focus":"기능 수준과 피로를 반영한 활동 지원","action":"개별 활동·휴식 계획을 따르고 지속 피로를 보고한다.","followup":"활동과 회복 시간을 비교해 인계한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E9","name":"보존적 돌봄","track":"신장질환 공통","reason":"간병사가 투석 시작·중단을 결정하지 않는다. 선택과 관계없이 편안함·일상 지원은 지속한다.","scenario":"환자와 의료진이 투석 외의 돌봄 목표를 논의하고 있다.","focus":"치료 선택과 환자 가치에 대한 지원","action":"환자의 질문·선호를 듣고 담당팀 설명을 연결한다.","followup":"확인된 목표와 지원 계획을 인계한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"renal-E10","name":"신장이식 후 지원","track":"신장질환 공통","reason":"면역억제제 등의 임의 중단을 권하지 않는다. 발열·소변 변화 등은 지침에 따라 보고한다.","scenario":"이식 환자가 증상이 없으니 처방약을 쉬겠다고 한다.","focus":"지속 복약·감염 관찰과 추적 계획","action":"이식팀에 상담하도록 연결하고 확인된 약·방문 계획을 돕는다.","followup":"복약 어려움과 이상 증상·연락 계획을 확인한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd/managing"},{"id":"dialysis-U01","name":"혈관 접근로 보호","track":"투석","reason":"접근로는 투석에 중요하다. 혈압 측정·채혈 부위 선택은 의료진이 접근로 정보를 보고 정한다.","scenario":"동정맥루가 있는 팔에 꽉 끼는 소매와 가방 끈이 압박을 준다.","focus":"투석 접근로 압박 예방","action":"압박을 줄이고 접근로가 있는 팔임을 돌봄팀과 공유한다.","followup":"일상복·자세·이동 중 반복 압박이 없는지 확인한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U02","name":"천자 부위 출혈","track":"투석","reason":"압박 방식은 기관 교육을 따르며 출혈을 보고만 하고 방치하지 않는다. 응급 호출과 직접 처치 권한을 구분한다.","scenario":"투석을 마친 부위에서 피가 계속 새고 환자가 어지럽다고 한다.","focus":"지속 출혈과 순환 저하 위험","action":"즉시 도움을 요청하고 교육받은 출혈 대응 절차를 시행한다.","followup":"출혈 시작·지속·어지럼과 시행한 대응을 의료진에게 인계한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U03","name":"접근로 감염 징후","track":"투석","reason":"감염이 의심되면 의료진 평가가 필요하다. 임의 연고·소독제·항생제를 적용하지 않는다.","scenario":"접근로 주변이 이전보다 붉고 뜨거우며 오한이 생긴다.","focus":"접근로 감염 가능성","action":"즉시 간호사에게 국소 변화와 전신 증상을 알린다.","followup":"발생 시각과 발열·오한 경과를 관찰한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U04","name":"투석 후 어지럼","track":"투석","reason":"체액 변화 등 원인은 평가가 필요하다. 모든 환자에게 소금물이나 많은 물을 주지 않는다.","scenario":"투석 종료 직후 일어나려던 환자가 어지러워 주저앉으려 한다.","focus":"투석 후 낙상과 혈압 변화 위험","action":"혼자 걷지 않게 돕고 즉시 담당자에게 알린다.","followup":"이동 허용 여부를 확인한 뒤 보조 인력과 방법을 정한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U05","name":"체중 기록","track":"투석","reason":"투석 전후 체중은 체액 평가 자료지만 목표 체중을 간병사가 설정하지 않는다.","scenario":"같은 환자의 체중을 서로 다른 시간·옷·저울로 재어 비교하려 한다.","focus":"체중 측정 조건의 일관성","action":"기관 계획에 맞춰 같은 조건을 사용하고 조건 차이를 기록한다.","followup":"전후 수치·단위·측정 시각을 확인하여 담당자에게 전달한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U06","name":"수분 계획","track":"투석","reason":"모든 투석 환자에게 동일한 양을 적용하지 않는다. 잔여 소변량과 상태를 의료진이 고려한다.","scenario":"환자는 입이 마르다며 하루 제한량과 별도로 국물을 더 마셔도 되는지 묻는다.","focus":"섭취량에 포함되는 액체의 확인","action":"개별 수분 계획과 국물 포함 기준을 간호사·영양사에게 확인한다.","followup":"실제 섭취량과 구강 불편을 기록하고 허용된 구강 관리를 돕는다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U07","name":"급성 호흡곤란","track":"투석","reason":"체액 과다 등 여러 원인이 가능하다. 다음 투석 때까지 기다리거나 기계를 임의로 연결하지 않는다.","scenario":"다음 투석을 기다리던 환자가 누우면 숨차고 갑자기 호흡이 힘들다고 한다.","focus":"응급 호흡 변화","action":"즉시 간호사를 호출하고 환자가 편한 허용 자세를 돕는다.","followup":"발생 시각·자세와의 관계·관찰한 호흡 변화를 인계한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U08","name":"칼륨 관리의 이해","track":"투석","reason":"칼륨 상태는 외모만으로 알 수 없다. 모든 과일 금지나 무제한 허용을 간병사가 결정하지 않는다.","scenario":"환자가 검사 결과를 모르면서 과일은 모두 건강하니 제한 없이 먹겠다고 한다.","focus":"개별 검사와 영양 처방의 필요","action":"투석 환자의 개인별 식이 지침을 확인하도록 연결한다.","followup":"식이 교육 내용을 환자가 자기 말로 설명하도록 돕는다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U09","name":"복막투석 혼탁 배액","track":"투석","reason":"혼탁 배액과 통증은 신속한 평가 대상이다. 간병사가 연결부를 열어 세척하거나 약물을 주입하지 않는다.","scenario":"복막투석 환자가 배가 아프고 배액이 평소보다 뿌옇다고 말한다.","focus":"복막염 가능성을 포함한 이상 변화","action":"즉시 투석 담당팀에 알리고 배액 관련 기관 지침을 따른다.","followup":"통증·혼탁 발견 시각과 다른 증상을 전달한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"dialysis-U10","name":"치료 일정과 인계","track":"투석","reason":"일정 변경의 임상 판단은 치료팀에 맡긴다. 간병사가 안전하게 한 번 쉬어도 된다고 보장하지 않는다.","scenario":"퇴원 후 이동편 문제로 다음 투석 방문을 건너뛰려 한다.","focus":"필수 치료 연속성의 위협","action":"투석실과 사회복지·이동 지원 담당자에게 사전에 연결한다.","followup":"예약·연락처·이동 수단·응급 시 연락 계획을 확인한다.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidney-failure/hemodialysis"},{"id":"U-01","name":"요실금 유형과 존엄","track":"비뇨기계","reason":"요실금은 유형과 원인에 따라 지원이 다르다. 실수를 벌주거나 수분을 일괄 제한하지 않는다.","scenario":"화장실에 도착하기 전에 소변이 새어 창피해한다.","focus":"배뇨 양상과 접근 장벽","action":"사생활을 보호하고 시간·상황을 기록해 배뇨 계획을 확인한다.","followup":"피부 상태와 계획의 실효성을 확인한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-02","name":"급성 요폐","track":"비뇨기계","reason":"급성 요폐는 즉시 평가가 필요할 수 있다. 배를 누르거나 도뇨관을 임의 삽입하지 않는다.","scenario":"아랫배가 아프고 소변이 마려운데 나오지 않는다.","focus":"배출 장애와 통증","action":"신속히 의료진에게 알리고 마지막 배뇨 시각을 전달한다.","followup":"평가 후 배뇨·통증 변화를 기록한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-03","name":"전립선비대 관련 배뇨","track":"비뇨기계","reason":"전립선비대 등 원인 평가는 의료진이 한다. 증상만으로 진단하거나 약을 임의 선택하지 않는다.","scenario":"줄기가 약하고 밤에 여러 번 화장실에 간다.","focus":"배뇨 곤란과 야간 낙상 위험","action":"야간 조명·동선을 확보하고 배뇨 양상을 보고한다.","followup":"야간 이동 안전과 잔여 불편을 확인한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-04","name":"요로감염 의심","track":"비뇨기계","reason":"소변 냄새나 혼탁만으로 감염을 확정하지 않는다. 항생제·검사 결정은 담당팀에 맡긴다.","scenario":"배뇨통과 발열이 새로 생겼다.","focus":"국소 배뇨 증상과 전신 변화","action":"증상·체온·발생 시각을 보고한다.","followup":"오한·처짐 등 악화가 있으면 재보고한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-05","name":"유치도뇨관 배액","track":"비뇨기계","reason":"폐쇄계를 임의 분리하거나 세척하지 않는다. 주머니는 지침에 따라 방광보다 낮게 유지한다.","scenario":"배액 주머니가 침대 위에 있고 줄이 눌려 있다.","focus":"역류·배액 방해 위험","action":"교육받은 범위에서 주머니 위치와 외부 눌림을 바로잡고 상태를 알린다.","followup":"배액 회복·누출·통증을 확인한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-06","name":"혈뇨","track":"비뇨기계","reason":"혈뇨를 단순 자극으로 넘기지 않는다. 원인은 다양하며 혈전이 배출을 막을 수 있다.","scenario":"소변에 피와 덩어리가 보이며 양이 줄었다.","focus":"출혈과 배출 장애","action":"즉시 보고하고 색·양·통증을 확인된 범위에서 전달한다.","followup":"처방된 관찰 주기와 증상 변화를 확인한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-07","name":"요로결석 의심","track":"비뇨기계","reason":"결석 외 원인도 가능하다. 발열·소변 감소 등을 함께 보고하고 물을 억지로 많이 먹이지 않는다.","scenario":"심한 옆구리 통증과 구토가 발생했다.","focus":"급성 통증과 동반 증상","action":"신속히 의료진에게 알리고 안전하게 곁을 지킨다.","followup":"통증·의식·배뇨 변화를 인계한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-08","name":"신경인성 방광","track":"비뇨기계","reason":"감각이 없다고 방광 문제가 없는 것은 아니다. 도뇨 등 처치는 권한 있는 담당자가 수행한다.","scenario":"척수 손상 환자가 배뇨 감각을 잘 느끼지 못한다.","focus":"감각 저하와 배뇨 계획 이행","action":"정해진 배뇨·관찰 계획과 도움 범위를 확인한다.","followup":"배뇨 기록과 피부·불편 변화를 공유한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-09","name":"회음부 피부 돌봄","track":"비뇨기계","reason":"마찰·강한 세정은 손상을 악화시킬 수 있다. 진균·압박손상 등 감별은 의료진에게 요청한다.","scenario":"요실금 후 회음부가 붉고 따갑다고 한다.","focus":"습기·자극과 피부 손상","action":"부드럽게 청결·건조를 돕고 보호 제품 지시를 확인한다.","followup":"발적·통증의 범위와 반응을 기록한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"},{"id":"U-10","name":"비뇨기 수술 후 인계","track":"비뇨기계","reason":"수술 종류별 관찰 기준을 확인하고 새 전신 증상을 함께 보고한다.","scenario":"수술 후 도뇨관 주변으로 피가 늘고 어지럽다고 한다.","focus":"수술 후 출혈·순환 변화","action":"즉시 호출하고 장치를 당기거나 조절하지 않는다.","followup":"처치 후 반응과 추가 관찰 지시를 확인한다.","source":"https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems/definition-facts"}]},{"id":"hematology","title":"혈액질환 전문간병사","category":"질환군 교육","scope":"빈혈·출혈 경향·혈전 의심 변화와 백혈병·림프종·골수종 심화","tracks":["혈액질환 공통","혈액암"],"units":[{"id":"hematology-E1","name":"빈혈 이해","track":"혈액질환 공통","reason":"빈혈에는 여러 원인이 있다. 외관만으로 철 결핍을 진단하거나 보충제를 권하지 않는다.","scenario":"환자가 창백해 보이면 모두 철분제를 먹으면 된다고 생각한다.","focus":"빈혈 원인의 다양성과 처방 확인","action":"피로·어지럼을 전달하고 원인·치료는 의료진 설명을 확인한다.","followup":"검사·치료 계획과 실제 증상을 인계한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E2","name":"출혈 경향","track":"혈액질환 공통","reason":"약·혈소판·응고 상태 등 원인을 스스로 확정하지 않는다.","scenario":"작은 충격에도 큰 멍이 생겨 환자가 걱정한다.","focus":"새 출혈 경향의 평가","action":"멍의 시작·범위·다른 출혈을 보고한다.","followup":"추가 외상을 줄이고 변화 경과를 기록한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E3","name":"응고 관련 약","track":"혈액질환 공통","reason":"출혈 정도에 따른 평가가 필요하며 간병사가 중단 기간을 정하지 않는다.","scenario":"처방된 항응고제를 먹는 환자가 코피 때문에 스스로 끊겠다고 한다.","focus":"출혈 보고와 처방 조정의 구분","action":"출혈 상태를 즉시 알리고 약 변경은 담당자에게 확인한다.","followup":"출혈·보고 시각과 확인된 지시를 전달한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E4","name":"한쪽 다리 부종","track":"혈액질환 공통","reason":"원인 확인 전 강한 자극을 피한다. 호흡곤란·가슴 통증 동반 시 즉시 응급 호출한다.","scenario":"한쪽 다리가 새로 붓고 아파 마사지해 달라고 한다.","focus":"혈전 등을 포함한 국소 변화","action":"마사지하지 않고 신속히 의료진에게 알린다.","followup":"증상 시작·동반 변화와 대응을 기록한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E5","name":"반복 채혈과 불안","track":"혈액질환 공통","reason":"검사를 독단적으로 취소하지 않고 이해와 편안함을 돕는다.","scenario":"잦은 검사 때문에 환자가 채혈을 두려워한다.","focus":"검사 관련 불안과 의사표현 지원","action":"걱정을 듣고 담당자에게 통증·설명 필요를 전달한다.","followup":"환자가 도움이 됐다고 한 방법을 인계한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E6","name":"기립 시 어지럼","track":"혈액질환 공통","reason":"빈혈이라는 이유로 모든 어지럼 원인을 단정하지 않는다.","scenario":"빈혈 환자가 혼자 일어서다 휘청거린다.","focus":"활동 중 낙상 위험","action":"안전하게 쉬도록 돕고 담당자에게 알린다.","followup":"활동 조건·회복·새 증상을 기록한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E7","name":"검사 결과 전달","track":"혈액질환 공통","reason":"단일 검사값과 임상 상태를 함께 평가해야 한다. 예후나 수혈 필요를 간병사가 결정하지 않는다.","scenario":"가족이 혈액검사 숫자를 보고 위험한지 간병사에게 확답을 요구한다.","focus":"검사 해석의 역할 경계","action":"담당 의료진의 설명을 연결하고 질문을 정리한다.","followup":"확인된 설명과 추가 질문을 구분해 남긴다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E8","name":"수혈 설명과 동의","track":"혈액질환 공통","reason":"간병사는 수혈의 적응증·위험 설명이나 동의를 대행하지 않는다.","scenario":"가족이 수혈 동의 설명을 간병사에게 대신 해 달라고 한다.","focus":"의료행위 설명·동의의 담당자 확인","action":"의료진 설명을 요청하고 환자의 질문·통역 필요를 전달한다.","followup":"의사소통 지원과 환자 표현을 기록한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E9","name":"혈액 안전","track":"혈액질환 공통","reason":"피부 손상·혈액 접촉 물품은 개인별 관리가 필요하다.","scenario":"피 묻은 면도기를 다른 환자도 써도 되는지 묻는다.","focus":"개인용품을 통한 혈액 노출 예방","action":"환자 간 공유하지 않고 기관의 오염물 지침을 따른다.","followup":"노출이 생기면 즉시 기관 절차로 보고한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"hematology-E10","name":"외래 연속성","track":"혈액질환 공통","reason":"증상 호전이 검사·치료 종료를 의미하지는 않는다.","scenario":"증상이 좋아져 혈액질환 추적 검사를 거르겠다는 환자다.","focus":"증상과 별개인 추적 계획","action":"담당팀과 일정·필요성을 확인하도록 돕는다.","followup":"예약·이동·복약 어려움과 연락 계획을 확인한다.","source":"https://www.nhlbi.nih.gov/health/anemia"},{"id":"blood-cancer-U01","name":"혈액암의 다양성","track":"혈액암","reason":"혈액암은 단일 질환이 아니다. 호중구·혈소판·뼈 병변 등의 위험도는 환자마다 다르다.","scenario":"백혈병 환자의 보호자가 골수종 환자와 똑같은 관리가 필요한지 묻는다.","focus":"질환·치료별 위험의 차이","action":"확인된 진단과 치료 단계에 맞는 개별 돌봄 지시를 확인한다.","followup":"담당팀이 지정한 주요 위험과 연락 기준을 인계한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U02","name":"발열과 감염","track":"혈액암","reason":"호중구 감소 여부가 불명확해도 새 발열·오한은 중요하다. 임의 해열제로 먼저 가리지 않는다.","scenario":"항암치료 중인 환자가 갑자기 오한과 열감을 호소한다.","focus":"감염에 대한 신속한 평가 필요","action":"체온 측정 때문에 보고를 늦추지 말고 즉시 담당자에게 알린다.","followup":"확인된 체온·시각·증상과 최근 치료 정보를 전달한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U03","name":"출혈성 변화","track":"혈액암","reason":"혈소판 수치는 외관으로 판단하지 못한다. 양치 도구·치실 사용 등은 개인별 지시를 확인한다.","scenario":"잇몸 출혈과 점상 피부 변화가 새로 보인다.","focus":"혈소판 저하 등을 포함한 출혈 위험","action":"변화를 간호사에게 알리고 외상을 줄이는 돌봄을 한다.","followup":"출혈 부위·지속·새 멍과 처치 후 경과를 기록한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U04","name":"빈혈과 활동","track":"혈액암","reason":"헤모글로빈 수치를 증상만으로 추정하지 않는다. 수혈 필요와 활동 허용 범위는 의료진이 판단한다.","scenario":"짧게 걸어도 두근거리고 어지러워 쉬어야 한다고 한다.","focus":"빈혈 등을 포함한 활동 내성 저하","action":"활동을 멈춰 안전을 돕고 증상을 보고한다.","followup":"활동 종류·증상·회복 시간과 새 호흡곤란을 관찰한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U05","name":"중심정맥관 보호","track":"혈액암","reason":"간병사가 연결부를 열거나 소독·교체를 독자적으로 하지 않는다.","scenario":"중심정맥관 드레싱이 젖고 가장자리가 들떠 있다.","focus":"관 관련 감염·고정 이상 위험","action":"간호사에게 알려 적절한 드레싱 관리를 받게 한다.","followup":"젖은 시각·원인·피부 변화와 대응을 인계한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U06","name":"수혈 중 새 증상","track":"혈액암","reason":"수혈 속도 조절·중단·검사 등은 의료진의 절차다. 간병사가 원인을 단정하지 않는다.","scenario":"수혈 중 환자가 오한과 숨참을 호소한다.","focus":"수혈 반응 가능성을 포함한 급성 변화","action":"즉시 담당 간호사를 호출하고 곁에서 상태를 관찰한다.","followup":"증상 시각과 관찰한 변화·도움 요청 시각을 전달한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U07","name":"이식 후 환경","track":"혈액암","reason":"환자별 면역 상태와 기관 지침이 우선이다. 개인 판단으로 격리를 해제하거나 추가한다는 뜻이 아니다.","scenario":"조혈모세포이식 후 방문객이 기침하면서 병실에 들어오려 한다.","focus":"감염 노출 예방","action":"방문 제한·마스크·손 위생 등 이식팀 지침을 확인해 안내한다.","followup":"방문객 증상과 노출 우려를 담당자에게 공유한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U08","name":"새 설사와 발진","track":"혈액암","reason":"감염·약물·이식 관련 합병증을 스스로 구분하지 않는다. 임의 지사제·연고로 평가를 지연시키지 않는다.","scenario":"이식 후 새 설사와 피부 발진이 함께 생겼다.","focus":"이식 후 합병증 평가 필요","action":"발생 시각·배변 횟수·피부 변화를 신속히 보고한다.","followup":"증상 범위와 섭취·배출 변화를 기록한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U09","name":"골수종과 뼈 통증","track":"혈액암","reason":"약해진 뼈는 작은 힘에도 손상될 수 있다. 강한 마사지와 강제 보행은 피한다.","scenario":"골수종 환자가 돌아눕다 갑자기 심한 허리 통증을 호소한다.","focus":"병적 골절 등을 포함한 뼈 손상 위험","action":"무리한 이동을 멈추고 의료진에게 통증과 상황을 알린다.","followup":"의료진이 허용한 이동 방식·인력·보조기를 확인한다.","source":"https://www.cancer.gov/types/leukemia"},{"id":"blood-cancer-U10","name":"구강 점막과 식사","track":"혈액암","reason":"구강 상태는 감염과 영양에 영향을 준다. 자극성 음식이나 세게 문지르기를 피한다.","scenario":"항암치료 후 입안이 헐어 먹기 어렵고 조금만 닿아도 아프다.","focus":"점막 손상과 섭취 저하","action":"통증·출혈 여부를 알리고 허용된 부드러운 구강·영양 관리를 돕는다.","followup":"실제 섭취·구강 불편·관리 후 반응을 인계한다.","source":"https://www.cancer.gov/types/leukemia"}]},{"id":"skin","title":"피부질환 전문간병사","category":"질환군 교육","scope":"옴·가피성 옴 환자 돌봄과 접촉·침구·환경관리, 피부 장벽·습기 손상·감염 의심·가려움·상처와 피부암 심화","tracks":["피부질환 공통","피부암"],"units":[{"id":"skin-E1","name":"피부 장벽","track":"피부질환 공통","reason":"강한 마찰·자극성 제품은 피하며 원인과 제품 선택은 담당팀과 정한다.","scenario":"건조하고 갈라진 피부가 세정 후 더 따갑다고 한다.","focus":"피부 장벽 손상과 자극 감소","action":"허용된 부드러운 세정·보습 계획을 확인한다.","followup":"제품 적용 후 불편·발적 변화를 살핀다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E2","name":"습기 관련 손상","track":"피부질환 공통","reason":"피부 변화의 원인을 간병사가 욕창으로 확정하지 않는다.","scenario":"실금 부위가 젖은 채 붉어지고 아프다고 한다.","focus":"습기 노출과 피부 보호","action":"사생활을 지키며 세정·건조·침구 교체를 돕고 보고한다.","followup":"습기 노출 시간과 관리 후 상태를 기록한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E3","name":"압박 손상과 구별","track":"피부질환 공통","reason":"압박손상과 습기 손상은 감별이 필요하다. 확정·단계 분류는 전문 평가를 따른다.","scenario":"뼈가 돌출된 부위와 실금 부위에 각각 다른 피부 변화가 보인다.","focus":"피부 변화의 위치·양상 구분","action":"두 부위를 구분해 보고하고 압박·습기 관리 계획을 따른다.","followup":"위치·색·통증·지시된 관찰을 인계한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E4","name":"급성 발적과 열감","track":"피부질환 공통","reason":"원인을 단순 피부 알레르기로 확정하지 않는다. 발열·의식 변화가 동반되면 즉시 도움을 요청한다.","scenario":"다리에 붉은 범위가 빠르게 넓어지고 열감·통증이 있다.","focus":"피부·연조직 감염 등을 포함한 변화","action":"신속히 의료진에게 전신 증상과 국소 변화를 알린다.","followup":"퍼지는 범위·시각·통증 경과를 기록한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E5","name":"물집과 통증","track":"피부질환 공통","reason":"외관만으로 병명을 확정하지 않으며 물집을 터뜨리지 않는다.","scenario":"한쪽 몸에 통증과 물집이 새로 생겼다.","focus":"감염성 피부질환 등을 포함한 평가 필요","action":"담당자에게 알리고 진단별 접촉·물품 지침을 확인한다.","followup":"발생 부위·시각·동반 증상과 지시를 인계한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E6","name":"옴 의심 상황","track":"피부질환 공통","reason":"옴은 진드기에 의한 피부 감염성 질환이다. 의심 환자는 의료진에게 보고하고 기관의 장갑·가운 등 접촉 예방 지침을 따른다. 침구·의류는 분리 수거하여 온수 세탁·고온 건조하고, 세탁 불가 물품은 기관이 정한 기간 밀봉 보관한다. 무증상 접촉자도 노출 사실을 보고하여 평가·치료 필요성을 확인한다. 가피성 옴은 가려움이 약하거나 없어도 전파 위험이 높을 수 있다. 진단·약물 처방·격리 해제는 의료진과 감염관리팀이 결정한다. 환자를 낙인찍지 않고 사생활을 보호한다.","scenario":"병동에서 가려움 증상이 겹쳐 감염관리팀이 평가 중이다.","focus":"집단 발생 가능성과 접촉 관리","action":"확인된 보호구·침구·접촉 지침을 따른다.","followup":"증상·접촉 우려를 정해진 경로로 보고한다.","source":"https://www.cdc.gov/scabies/php/public-health-strategy/"},{"id":"skin-E7","name":"알레르기 의심 변화","track":"피부질환 공통","reason":"피부 문제로만 보지 않는다. 호흡·의식 변화를 함께 관찰한다.","scenario":"새 제품 사용 뒤 발진이 생기고 입술 부종·숨참을 호소한다.","focus":"전신 알레르기 반응을 포함한 응급 변화","action":"즉시 응급 호출하고 사용 제품·시각을 전달한다.","followup":"의료진 인계까지 증상 진행을 알린다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E8","name":"피부 찢김","track":"피부질환 공통","reason":"임의로 피부를 잘라내거나 일반 접착제로 붙이지 않는다.","scenario":"얇은 피부에 테이프를 떼다가 피부가 벗겨졌다.","focus":"취약 피부의 추가 손상 예방","action":"더 당기지 않고 간호사에게 상처 관리를 요청한다.","followup":"원인·부위·출혈과 예방 계획을 인계한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E9","name":"만성 가려움","track":"피부질환 공통","reason":"원인이 피부 외 질환·약물일 수도 있어 독자 진단하지 않는다.","scenario":"밤마다 긁어 잠을 못 자고 피부 상처가 반복된다.","focus":"수면·피부 손상에 대한 통합 지원","action":"가려움과 생활 영향을 보고하고 허용된 피부·환경 관리를 돕는다.","followup":"유발 조건·수면 방해·관리 반응을 기록한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-E10","name":"외용제와 기록","track":"피부질환 공통","reason":"외용제도 처방·제품별 사용법을 지켜야 한다. 섞어 쓰거나 횟수를 임의로 늘리지 않는다.","scenario":"여러 연고가 있어 환자가 같은 부위에 모두 바르려 한다.","focus":"외용제별 부위·방법 확인","action":"담당자에게 제품·부위·사용 지시를 확인한다.","followup":"확인된 사용과 피부 반응을 인계한다.","source":"https://www.nhs.uk/conditions/cellulitis/"},{"id":"skin-cancer-U01","name":"피부암 종류","track":"피부암","reason":"피부암은 다양한 유형이며 외관만으로 예후를 판단하지 않는다.","scenario":"환자가 모든 피부암은 가벼우니 추적 진료가 필요 없다고 말한다.","focus":"피부암 유형과 경과의 차이","action":"본인 진단과 추적 계획을 의료진에게 확인하도록 돕는다.","followup":"환자가 알고 있는 진단명·예약·질문을 정리한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U02","name":"수술 부위 출혈","track":"피부암","reason":"드레싱을 반복해 떼어 상처를 확인하거나 임의 약물을 바르지 않는다.","scenario":"절제 부위 드레싱에 피가 새로 번지고 계속 넓어진다.","focus":"수술 상처 출혈 가능성","action":"즉시 간호사에게 알리고 교육받은 출혈 대응 절차를 따른다.","followup":"번짐·시각·통증과 대응 후 변화를 기록한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U03","name":"상처 감염 징후","track":"피부암","reason":"일반적인 회복인지 감염인지는 의료진이 평가한다. 임의 소독제·민간요법을 적용하지 않는다.","scenario":"수술 부위가 더 붉고 뜨겁고 통증이 커졌다고 한다.","focus":"상처 감염 등을 포함한 변화","action":"국소 변화와 전신 증상을 담당자에게 보고한다.","followup":"변화 범위와 발열·분비물 관찰을 전달한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U04","name":"피부 이식 부위 보호","track":"피부암","reason":"이식·피판 부위는 수술별 보호 지침이 필요하다. 보습제도 임의로 바르지 않는다.","scenario":"이식 부위가 가렵다며 옷 위로 세게 문지르려 한다.","focus":"재건 피부의 마찰·손상 예방","action":"마찰을 줄이고 가려움과 허용 관리법을 간호사에게 확인한다.","followup":"옷·침구의 압박과 가려움 지속 여부를 살핀다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U05","name":"림프부종","track":"피부암","reason":"림프부종·감염·혈전 등 원인을 구분해야 한다. 압박 강도나 마사지를 간병사가 정하지 않는다.","scenario":"림프절 수술 뒤 한쪽 팔이 무겁고 새로 붓는다고 한다.","focus":"수술 후 부종의 평가 필요","action":"부종 변화와 통증·발적 여부를 보고한다.","followup":"처방된 관리 후 부종·피부 상태와 기능을 기록한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U06","name":"자외선 보호","track":"피부암","reason":"상처가 열린 부위와 정상 피부의 관리가 다를 수 있다. 모든 제품을 상처 위에 바로 바르지 않는다.","scenario":"외출할 때 수술 부위를 햇볕에 오래 노출하려 한다.","focus":"치료 후 피부 보호와 자외선 노출 감소","action":"의료진 지시에 맞는 의복·그늘·차단 방법을 확인한다.","followup":"환자가 실행할 외출 보호 계획을 확인한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U07","name":"새 병변 관찰","track":"피부암","reason":"사진은 진단을 대신하지 않는다. 개인 휴대폰이나 공개 대화방에 올리지 않는다.","scenario":"환자가 기존 점이 달라졌다고 말하며 사진을 찍어 비교하고 싶어 한다.","focus":"피부 변화의 객관적 전달","action":"동의와 기관 절차에 따라 변화 시점·모양을 기록해 진료 연결을 돕는다.","followup":"촬영·보관 동의와 진료 요청 결과를 남긴다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U08","name":"면역치료와 설사","track":"피부암","reason":"음식 탓으로만 돌리지 않는다. 임의 지사제로 악화를 가리지 않는다.","scenario":"면역치료 중 평소 없던 잦은 설사와 복통이 생겼다.","focus":"치료 관련 장 이상 등을 포함한 변화","action":"증상과 치료 정보를 신속히 의료진에게 보고한다.","followup":"배변 횟수·혈변 여부·섭취와 불편 변화를 기록한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U09","name":"심한 피부 반응","track":"피부암","reason":"흔한 가려움으로 넘기지 않는다. 원인 약 판단과 처치는 전문 평가가 필요하다.","scenario":"치료 중 물집과 피부 벗겨짐이 새로 생기고 입안도 아프다.","focus":"심한 피부·점막 반응 가능성","action":"즉시 의료진에게 알리고 피부를 추가로 자극하지 않는다.","followup":"발생 시각·퍼지는 범위·전신 증상을 전달한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-cancer-U10","name":"외모와 정서","track":"피부암","reason":"흉터를 사소하다고 축소하거나 근거 없는 완전 회복을 약속하지 않는다.","scenario":"얼굴 흉터 때문에 외출을 피하며 낙담한다.","focus":"외모 변화와 사회적 참여 지원","action":"감정을 듣고 환자가 원하는 상담·외출 지원을 연결한다.","followup":"환자가 선택한 목표와 필요한 도움을 인계한다.","source":"https://www.cancer.gov/types/skin"},{"id":"skin-treatment","name":"옴 동시 치료·도포·생활관리","track":"옴 환자 돌봄","reason":"동거인·밀접 접촉자는 증상이 없어도 같은 시기에 치료하도록 조율한다. 성인 일반 옴의 퍼메트린 5% 크림은 CDC 지침상 목 아래 전신에 바르고 8~14시간 뒤 씻는 예시가 있으나 국내 제품 설명서와 개인별 처방을 우선한다. 약 1주 후 추가 도포가 필요할 수 있어 처방을 확인한다. 다른 약·소아·고령자·가피성 옴에 동일 일정을 임의 적용하지 않는다. 최근 3일 사용 물품을 세탁·고온 건조하고, 세탁 불가 물품은 최소 72시간~1주 밀봉한다. 피부나 실내에 살충제를 분무하지 않는다. 치료 후 가려움만으로 실패를 단정하지 말고 새 발진이나 지속 증상을 보고한다. 상세 참고자료의 치료·환경관리 절차를 함께 읽는다.","scenario":"옴 환자의 가족이 자신은 가렵지 않다며 치료를 미루고, 환자는 연고를 바른 즉시 씻으려 한다.","focus":"접촉자 동시 치료와 약제별 도포·세척 일정 확인","action":"가족도 의료진에게 연결하여 동시 치료를 조율하고 환자의 약명·농도·도포 범위·세척 시각을 처방과 대조한다.","followup":"접촉자 치료 조율, 실제 도포·세척 시각, 세탁·밀봉 처리, 피부 반응과 재평가 지시를 기록한다.","source":"https://www.cdc.gov/scabies/hcp/clinical-care/index.html"}]},{"id":"endocrine","title":"내분비·대사질환 전문간병사","category":"질환군 교육","scope":"당뇨·혈당 변화·발 관리·갑상선 수술과 갑상선암 심화","tracks":["당뇨·대사 돌봄","갑상선암"],"units":[{"id":"endocrine-E1","name":"당뇨와 일상 계획","track":"당뇨·대사 돌봄","reason":"혈당 관리는 여러 요인이 연관된다. 간병사가 식사량만 보고 약을 조절하지 않는다.","scenario":"환자가 식사·활동·약 계획을 각각 따로 생각한다.","focus":"식사·활동·투약의 연계","action":"현재 지시를 함께 확인하고 실제 섭취·활동 변화를 공유한다.","followup":"계획과 실제 수행의 차이를 인계한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E2","name":"저혈당 의심","track":"당뇨·대사 돌봄","reason":"증상만으로 혈당을 확정하지 않는다. 측정·치료는 기관 절차와 훈련 범위에 따른다.","scenario":"당뇨 환자가 식은땀과 떨림을 보이며 반응이 둔해진다.","focus":"저혈당 등을 포함한 급성 변화","action":"즉시 의료진을 호출하고 의식 저하 시 경구 투여를 하지 않는다.","followup":"증상 시각·최근 섭취·확인된 투약과 대응을 전달한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E3","name":"심한 고혈당 관련 변화","track":"당뇨·대사 돌봄","reason":"단순 갈증으로만 보지 않는다. 인슐린을 임의 추가하거나 물만 주며 기다리지 않는다.","scenario":"당뇨 환자가 심한 갈증·구토·처짐을 새로 호소한다.","focus":"급성 대사 이상 가능성","action":"즉시 담당자에게 증상과 경과를 알린다.","followup":"호흡·의식·확인된 측정값과 보고 시각을 남긴다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E4","name":"섭취 감소와 약","track":"당뇨·대사 돌봄","reason":"먹지 않았다는 이유로 간병사가 임의 중단·감량하지 않는다. 치료팀이 약 종류와 상태를 고려한다.","scenario":"식사를 거의 못 했는데 예정된 당뇨약 시간이 다가온다.","focus":"섭취 변화와 투약 계획 확인","action":"실제 섭취 상태를 간호사에게 알려 투약 판단을 받는다.","followup":"담당자가 확인한 계획과 실제 섭취를 인계한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E5","name":"혈당 측정 위생","track":"당뇨·대사 돌봄","reason":"채혈 펜은 바늘만 바꿔 공유하지 않는다. 측정은 교육·업무 범위와 감염관리 기준을 지킨다.","scenario":"여러 환자에게 같은 채혈 펜을 쓰려는 상황을 발견했다.","focus":"혈액 매개 감염 예방","action":"사용을 진행하지 않고 담당자에게 환자별 기구 지침을 확인한다.","followup":"노출 우려가 있으면 기관 보고 절차를 따른다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E6","name":"발의 감각 저하","track":"당뇨·대사 돌봄","reason":"감각이 둔하면 화상을 늦게 알아차릴 수 있다. 발 피부·신발을 살핀다.","scenario":"발이 저린 환자가 뜨거운 찜질로 풀겠다고 한다.","focus":"감각 저하에 따른 화상 위험","action":"직접 열 자극을 피하도록 돕고 안전한 발 관리 지시를 확인한다.","followup":"상처·물집·색 변화는 담당자에게 알린다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E7","name":"발 상처","track":"당뇨·대사 돌봄","reason":"통증이 없다고 안전한 것은 아니다. 굳은살 절제나 임의 약품 처치를 하지 않는다.","scenario":"당뇨 환자의 발가락에 작은 상처가 있는데 통증은 없다고 한다.","focus":"통증 없는 상처의 평가 필요","action":"상처를 보고하고 전문적인 관리 계획을 확인한다.","followup":"상처 주변 변화와 허용 보행·보호 방법을 인계한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E8","name":"시력 저하와 자가관리","track":"당뇨·대사 돌봄","reason":"스스로 하라는 말만으로 해결되지 않는다. 도움 필요와 환자 선택을 함께 고려한다.","scenario":"시력이 나빠 약 이름과 기기 숫자를 읽기 어렵다고 한다.","focus":"감각 기능을 고려한 자기관리 지원","action":"담당팀과 읽기 보조·복약 확인·가족 교육 방법을 정한다.","followup":"실제로 가능한 단계와 필요한 도움을 기록한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E9","name":"스테로이드와 혈당","track":"당뇨·대사 돌봄","reason":"스테로이드가 혈당에 영향을 줄 수 있으나 간병사가 약을 끊거나 혈당을 예측하지 않는다.","scenario":"스테로이드 치료 중 혈당 추적을 추가하라는 지시를 받았다.","focus":"치료가 대사 상태에 미치는 영향","action":"지정된 관찰·보고를 지원하고 섭취·증상 변화를 전달한다.","followup":"확인된 측정과 의료진 지시를 구분해 인계한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"endocrine-E10","name":"퇴원 후 저혈당 계획","track":"당뇨·대사 돌봄","reason":"의식 저하나 삼킴 불안전 상태에서는 경구 투여가 위험하다. 개별 행동계획을 익힌다.","scenario":"가족이 환자가 어지러우면 무조건 음료를 먹이겠다고 한다.","focus":"의식·삼킴 상태와 개인별 응급 계획","action":"교육팀에 저혈당 대응과 경구 투여 금기 상황 설명을 요청한다.","followup":"가족이 응급 연락·행동 순서를 설명하도록 확인한다.","source":"https://www.cdc.gov/diabetes/treatment/index.html"},{"id":"thyroid-U01","name":"수술 종류와 계획","track":"갑상선암","reason":"같은 갑상선암이라도 수술·약·검사 계획은 다르다. 옆 환자의 처방을 적용하지 않는다.","scenario":"환자가 갑상선 수술을 받았으나 일부 절제인지 전절제인지 모른다.","focus":"수술 범위에 따른 추적·복약 계획","action":"진료 기록과 담당자의 설명으로 본인 계획을 확인한다.","followup":"확인된 복약·검사·연락 계획을 정리한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U02","name":"목 부종과 숨참","track":"갑상선암","reason":"출혈·혈종 등은 신속한 평가가 필요하다. 상처를 열거나 부위를 세게 누르지 않는다.","scenario":"목 수술 뒤 갑자기 목이 붓고 조이는 느낌과 숨참을 호소한다.","focus":"기도 압박을 포함한 수술 후 응급 변화","action":"즉시 응급 호출하고 환자를 혼자 두지 않는다.","followup":"증상 시작 시각·부종·호흡 변화와 대응을 전달한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U03","name":"저림과 경련","track":"갑상선암","reason":"칼슘 상태는 검사와 의료진 평가가 필요하다. 임의 칼슘제 용량을 정하지 않는다.","scenario":"수술 후 입 주변과 손끝이 저리고 손이 오그라드는 느낌을 말한다.","focus":"저칼슘혈증 등을 포함한 평가 필요","action":"즉시 간호사에게 저림·경련 양상을 보고한다.","followup":"증상의 부위·시각·진행과 확인된 처방을 인계한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U04","name":"목소리 변화","track":"갑상선암","reason":"일시 변화와 신경·연하 문제를 간병사가 구분하지 않는다. 경구 섭취 안전 지시를 확인한다.","scenario":"수술 후 목소리가 평소와 달라지고 삼킬 때 기침한다.","focus":"발성·삼킴 기능 변화","action":"목소리와 식사 중 기침을 담당자에게 알린다.","followup":"변화 지속·호흡 불편·새 식이 지시를 기록한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U05","name":"호르몬제 일정","track":"갑상선암","reason":"증상 유무만으로 약 필요성을 정하지 않는다. 약 조절과 검사 해석은 의료진 영역이다.","scenario":"환자가 증상이 없으니 처방된 호르몬제를 며칠 쉬겠다고 한다.","focus":"지속 복약과 임의 중단 예방","action":"담당자에게 상담하도록 돕고 처방 일정의 확인을 지원한다.","followup":"실제 복용 확인과 빠뜨린 상황을 담당자에게 전달한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U06","name":"복약과 보충제","track":"갑상선암","reason":"일반식품처럼 보여도 약의 흡수 등에 영향을 줄 수 있다. 간병사가 간격을 임의로 정하지 않는다.","scenario":"환자가 처방약과 새 건강보조제를 함께 먹어도 되는지 묻는다.","focus":"복용 간격·상호작용 확인","action":"약사·의료진에게 제품명과 복약 계획을 확인하도록 연결한다.","followup":"확인받은 복용 방법을 환자가 설명하도록 돕는다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U07","name":"방사성요오드 계획","track":"갑상선암","reason":"투여량과 상황에 따라 지침이 달라 일률적인 제한 기간을 만들지 않는다.","scenario":"치료 후 접촉 제한 안내가 있는데 가족이 일반 항암치료와 같다고 생각한다.","focus":"방사선 안전 지시의 개별 적용","action":"핵의학과의 서면 거리·기간·생활 지침을 확인한다.","followup":"동거인·어린이·임신 가능 가족 관련 질문을 담당팀에 전달한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U08","name":"목 운동과 통증","track":"갑상선암","reason":"회복 단계별 제한을 확인해야 한다. 통증을 참으며 늘리는 것은 목표가 아니다.","scenario":"목이 뻣뻣하다며 가족이 목을 강하게 돌려주려 한다.","focus":"수술 부위 보호와 허용 운동","action":"강제 움직임을 피하고 의료진이 교육한 운동 범위를 따른다.","followup":"허용 동작 수행과 통증 변화를 기록한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U09","name":"상처 관찰","track":"갑상선암","reason":"상처를 짜거나 남은 항생제를 임의 복용하지 않는다.","scenario":"퇴원 후 목 상처에서 새 분비물과 열감이 생긴다.","focus":"상처 합병증 가능성","action":"기관 연락 지침에 따라 신속히 수술팀에 알린다.","followup":"분비물·발적·발열 여부와 연락 결과를 남긴다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"},{"id":"thyroid-U10","name":"예후 설명의 한계","track":"갑상선암","reason":"질환명만으로 예후와 고통을 단정하지 않는다. 재발 추적과 개인 목표가 중요하다.","scenario":"가족이 갑상선암이면 모두 가볍다며 환자의 불안을 무시한다.","focus":"진단별 개인차와 정서 지지","action":"불안을 듣고 본인의 병리·치료 설명을 담당의에게 확인하도록 돕는다.","followup":"환자가 이해한 추적 일정과 남은 질문을 기록한다.","source":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/thyroid-surgery"}]},{"id":"head-neck","title":"두경부암 전문간병사","category":"질환군 교육","scope":"설암·후두암 통합: 구강·삼킴·기도·발성·영양·재건 후 돌봄","tracks":["설암","후두암"],"units":[{"id":"tongue-U01","name":"혀의 기능과 돌봄","track":"설암","reason":"혀는 음식 처리와 발음에 관여한다. 말을 못해도 이해하지 못한다고 단정하지 않는다.","scenario":"혀 수술 후 환자가 음식 이동과 발음 모두 어렵다고 말한다.","focus":"삼킴과 의사소통 기능의 동시 지원","action":"삼킴 허용 범위와 의사소통 도구를 각각 확인한다.","followup":"식사와 대화에서 필요한 도움을 구분해 기록한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U02","name":"수술 후 부종","track":"설암","reason":"수술 후 흔한 붓기라며 기다리지 않는다. 입안에 물건을 넣거나 붓기를 누르지 않는다.","scenario":"입안과 목의 붓기가 빠르게 커지고 숨쉬기 어렵다고 한다.","focus":"기도에 영향을 줄 수 있는 급격한 부종","action":"즉시 응급 호출하고 환자를 혼자 두지 않는다.","followup":"부종 시작·호흡·반응 변화를 인계한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U03","name":"구강 출혈","track":"설암","reason":"물로 세게 헹구거나 상처를 임의로 건드리지 않는다. 원인과 지혈 처치는 의료진 판단이다.","scenario":"입안에서 계속 피가 나고 삼키기 힘들다고 호소한다.","focus":"출혈과 기도 안전","action":"즉시 간호사를 부르고 교육받은 안전 절차를 따른다.","followup":"출혈의 관찰 양상과 호흡·삼킴 변화를 보고한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U04","name":"연하 계획","track":"설암","reason":"구강 상처와 재건 상태에 따라 계획이 다르다. 임의로 물 시험을 하지 않는다.","scenario":"퇴원 전 환자가 물부터 마셔 연습하겠다고 하지만 허용 여부가 불분명하다.","focus":"수술 후 삼킴 안전 확인","action":"담당팀의 식이·물·자세 지시를 먼저 확인한다.","followup":"교육된 자세와 질감을 환자·가족이 설명하도록 돕는다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U05","name":"구강 청결","track":"설암","reason":"강한 마찰과 자극성 용액은 피한다. 수술 부위와 출혈 위험을 확인해야 한다.","scenario":"입안이 아파 구강 관리를 모두 거부하고 있다.","focus":"통증을 고려한 부드러운 구강 관리","action":"통증을 보고하고 의료진이 정한 도구·방법으로 허용된 관리를 돕는다.","followup":"관리 전후 통증·출혈·구강 불편을 기록한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U06","name":"입마름","track":"설암","reason":"모든 환자에게 물이나 사탕이 안전하지는 않다. 삼킴과 치아 관리 계획을 함께 확인한다.","scenario":"방사선치료 중 입이 말라 말하고 먹기 어렵다고 한다.","focus":"구강 건조의 기능 영향","action":"금식·수분 지시를 확인하고 처방된 구강 보습 방법을 돕는다.","followup":"환자가 편안해진 방법과 지속되는 섭취 어려움을 인계한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U07","name":"영양관과 자율성","track":"설암","reason":"영양관은 모든 기능의 상실을 뜻하지 않는다. 주입·관 조작은 교육과 업무 범위를 지킨다.","scenario":"경관영양 중인 환자가 혼자 아무것도 못한다며 낙담한다.","focus":"영양 보조 중 남은 자기관리 능력","action":"환자가 할 수 있는 세안·의사표현 등 활동을 함께 정한다.","followup":"독립 수행한 활동과 도움이 필요했던 단계를 기록한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U08","name":"발음 보조","track":"설암","reason":"발음의 명료도와 생각의 내용은 다르다. 언어치료팀의 전략을 활용한다.","scenario":"환자의 말을 주변에서 반복해 못 알아듣자 환자가 대화를 포기한다.","focus":"표현 수단 접근성","action":"글·그림·짧은 선택 질문을 제공하고 충분히 기다린다.","followup":"가장 편한 표현 도구를 병실과 인계에 일관되게 적용한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U09","name":"입 벌림 제한","track":"설암","reason":"상처·재건 부위 상태를 모르고 강제 운동하면 손상 위험이 있다.","scenario":"치료 후 입을 벌리기 어렵고 가족이 손으로 세게 벌려주려 한다.","focus":"운동의 처방·안전 범위","action":"강제로 벌리지 않도록 설명하고 재활팀의 개인별 운동 지시를 확인한다.","followup":"지시된 운동의 수행 정도와 통증을 기록한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"tongue-U10","name":"외모 변화와 면회","track":"설암","reason":"면회를 강요하거나 허락 없이 사진을 공유하지 않는다. 환자에게 선택권을 둔다.","scenario":"환자가 수술 후 얼굴 모습 때문에 면회를 거절한다.","focus":"신체상과 사생활 존중","action":"환자 의사를 존중하고 원할 때 상담·가족 소통을 연결한다.","followup":"허용한 면회·사진 범위와 원하는 지원을 기록한다.","source":"https://www.cancer.gov/types/head-and-neck/patient/adult/lip-mouth-treatment-pdq"},{"id":"laryngeal-U01","name":"수술 후 기도 구조","track":"후두암","reason":"전후두절제와 일반 기관절개는 같지 않다. 코·입만으로 산소를 주는 대응은 적절한 기도 공급이 되지 않는다.","scenario":"전후두절제 환자의 기록에 목의 영구 기공으로 호흡한다고 되어 있다.","focus":"전후두절제 후 코·입과 폐의 분리","action":"목 기공이 기도임을 인계하고 응급팀에 수술 종류를 알릴 준비를 한다.","followup":"침상 표지와 기관별 응급 기도 계획을 담당자와 확인한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U02","name":"기공 가림 예방","track":"후두암","reason":"기공은 호흡 통로다. 관 안에 손가락이나 도구를 넣어 확인하지 않는다.","scenario":"목 기공 위로 침구가 올라오고 환자가 답답해한다.","focus":"호흡 통로의 외부 가림","action":"외부 가림을 즉시 없애고 호흡 상태를 살피며 간호사를 부른다.","followup":"가림 원인과 호흡 회복 여부를 전달한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U03","name":"급성 호흡 이상","track":"후두암","reason":"흡인·관 교환·산소 적용은 훈련과 기관 기도 알고리즘에 따른다. 간병사가 임의 삽입하지 않는다.","scenario":"전후두절제 환자가 목 기공에서 거친 소리를 내며 숨쉬기 힘들어한다.","focus":"기공·기도 응급 변화","action":"즉시 응급 호출하며 전후두절제 환자임을 명확히 알린다.","followup":"증상 시각·분비물·호흡과 반응 변화를 보고한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U04","name":"가습과 분비물","track":"후두암","reason":"상기도 가습 기능이 바뀔 수 있다. 기공에 물을 붓거나 임의 흡인을 하지 않는다.","scenario":"분비물이 평소보다 끈끈해지고 기공 주변에 마른 분비물이 보인다.","focus":"가습·분비물 관리 계획 확인","action":"간호사에게 알려 처방된 가습·보호 장치 관리 보조를 따른다.","followup":"교육된 관리 후 분비물과 호흡 불편을 관찰한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U05","name":"목욕 안전","track":"후두암","reason":"목 기공은 피부 상처만이 아니라 기도 입구다. 보통 샤워처럼 물에 노출시키지 않는다.","scenario":"환자가 샤워 물줄기를 목 기공 쪽으로 향하려 한다.","focus":"기공으로 물이 들어갈 위험","action":"물을 피하도록 돕고 기관이 교육한 방수·세정 방법을 따른다.","followup":"환자가 안전한 목욕 방법을 설명하도록 확인한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U06","name":"비음성 의사표현","track":"후두암","reason":"발성이 어려워도 이해와 선택은 가능할 수 있다. 가족에게만 묻지 않는다.","scenario":"수술 후 목소리를 내지 못하는 환자가 호출 의사를 전달하기 어렵다.","focus":"의사소통 접근성과 호출권","action":"손이 닿는 호출벨·글판·그림판을 준비하고 사용을 확인한다.","followup":"환자의 표현 신호를 모든 교대자에게 공유한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U07","name":"발성 보조기","track":"후두암","reason":"기기별 관리가 다르며 보철물 이탈·누출은 평가가 필요하다.","scenario":"발성 보조기를 잘 못 쓰는 환자에게 가족이 내부 부품을 빼서 고치려 한다.","focus":"보조기·보철물의 전문 관리 필요","action":"임의 분해를 막고 언어치료·담당팀에 사용 교육을 요청한다.","followup":"사용 어려움과 교육 후 가능한 단계를 기록한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U08","name":"식사 재개","track":"후두암","reason":"발성 여부만으로 삼킴 안전을 판단하지 않는다. 수술 범위와 상처 상태를 함께 고려한다.","scenario":"수술 후 환자가 말하지 못해도 삼킬 수 있으니 식사를 달라고 한다.","focus":"수술 회복과 경구 섭취 허용 확인","action":"담당팀의 식사 재개·질감 지시를 확인한 뒤 보조한다.","followup":"식이 지시·통증·섭취 중 이상을 인계한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U09","name":"목 기공 출혈","track":"후두암","reason":"마른 분비물 탓으로 단정하지 않는다. 깊숙한 세정이나 임의 지혈 도구 사용을 피한다.","scenario":"기공 주변에서 평소와 다른 출혈이 생겼다.","focus":"기도 부위 출혈의 긴급 평가","action":"즉시 의료진에게 알리고 호흡 상태를 함께 관찰한다.","followup":"출혈 시각·관찰 양상·호흡 변화와 대응을 기록한다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"},{"id":"laryngeal-U10","name":"외출·퇴원 준비","track":"후두암","reason":"의사소통 도구와 응급 기도 정보는 연속 돌봄의 일부다. 개별 계획에 맞춰 준비한다.","scenario":"환자가 외출 중 문제가 생기면 말을 못해 설명할 수 없을까 걱정한다.","focus":"기도 정보와 비상 의사소통 준비","action":"담당팀과 기도 정보 카드·연락처·필요 물품 계획을 확인한다.","followup":"환자·가족이 호출·정보 전달 방법을 시연하도록 돕는다.","source":"https://www.cancer.org/cancer/types/laryngeal-and-hypopharyngeal-cancer/treating/surgery.html"}]},{"id":"dementia","title":"치매전문간병사","category":"특화 교육","scope":"알츠하이머병·혈관성·혼합·전두측두엽 치매·행동변이·의미 치매·진행성 비유창 실어증·루이소체·파킨슨병 치매·기타 뇌손상·치료 가능한 인지저하 원인·전신 질환·섬망·우울 감별","tracks":["알츠하이머병","혈관성·혼합 치매","전두측두엽 치매 개관","행동변이 전두측두엽치매","의미 치매·의미변이 원발진행실어증","진행성 비유창 실어증","단어찾기형 PPA와 언어 감별","루이소체 치매","파킨슨병 치매","기타 뇌손상에 의한 인지장애","정상압수두증 등 평가 가능한 원인","약물·비타민 결핍 관련 인지저하","전신적 질환과 인지 변화","섬망과 치매의 구별","우울과 인지저하","행동심리증상과 통증","배회·실종 예방과 자율성","치매의 식사·삼킴 돌봄","의사결정 지원과 가족 부담","진행 단계·완화돌봄·통합 인계"],"units":[{"id":"D-01","name":"알츠하이머병","track":"치매 유형·감별·맞춤 돌봄","reason":"알츠하이머병에서는 최근 일의 기억이 어려울 수 있다. 반복 질문을 고집으로 단정하지 않고 익숙한 단서를 제공한다.","scenario":"방금 식사한 환자가 다시 식사를 요청하며 불안해한다.","focus":"최근 기억 저하와 정서적 요구","action":"논쟁하지 않고 배고픔·불편을 확인하며 일정과 식사 기록을 함께 살핀다.","followup":"안심 여부와 실제 섭취량을 기록한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-02","name":"혈관성·혼합 치매","track":"치매 유형·감별·맞춤 돌봄","reason":"혈관성 인지장애와 알츠하이머병이 함께 있을 수 있다. 새 뇌졸중 징후를 치매 진행으로 넘기지 않는다.","scenario":"기존 인지저하 환자에게 갑자기 말 어눌함과 한쪽 힘 빠짐이 생겼다.","focus":"기존 치매와 구분할 급성 국소 신경 변화","action":"즉시 응급 도움을 요청하고 마지막 정상 시각을 전달한다.","followup":"응급 인계와 삼킴 평가 전 경구 섭취 제한 지시를 확인한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-03","name":"전두측두엽 치매 개관","track":"치매 유형·감별·맞춤 돌봄","reason":"전두측두엽 변성에서는 행동이나 언어 문제가 앞설 수 있다. 임상 증후군 이름과 병리 진단은 같지 않으며 간병사가 유형을 확정하지 않는다.","scenario":"기억은 비교적 유지되지만 행동·언어 변화 때문에 가족이 성격 탓이라고 한다.","focus":"기억 이외의 행동·언어 기능 변화","action":"변화의 시작과 일상 영향을 관찰해 진료팀에 전달한다.","followup":"가족과 일관된 대응 계획을 공유한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-04","name":"행동변이 전두측두엽치매","track":"치매 유형·감별·맞춤 돌봄","reason":"bvFTD의 행동 변화를 도덕성 문제로 취급하지 않는다. 허기·약물·불편 등 다른 원인도 살핀다.","scenario":"환자가 남의 음식을 집어 먹고 거리낌 없는 말을 반복한다.","focus":"탈억제·충동·식행동 변화","action":"비난 없이 음식 접근과 환경 자극을 조정하고 안전을 확보한다.","followup":"선행 상황·행동·대응 후 반응을 기록한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-05","name":"의미 치매·의미변이 원발진행실어증","track":"치매 유형·감별·맞춤 돌봄","reason":"의미 치매는 의미변이 원발진행실어증(svPPA)과 관련된 용어다. 단어를 반복 시험하거나 큰 소리로 말하는 것만으로 해결되지 않는다.","scenario":"말은 유창하지만 컵이라는 단어와 물건의 의미를 이해하기 어렵다.","focus":"단어·사물 의미 이해의 점진적 저하","action":"실물과 시범으로 한 단계씩 설명하고 이해를 확인한다.","followup":"도움이 된 실물·그림 단서를 인계한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-06","name":"진행성 비유창 실어증","track":"치매 유형·감별·맞춤 돌봄","reason":"비유창·비문법변이 PPA에서는 말 산출이 힘들 수 있다. 말이 느리다고 이해·판단 능력을 모두 없다고 보지 않는다.","scenario":"환자가 뜻은 표현하려 하지만 말을 힘들게 끊어 하고 문법이 단순해졌다.","focus":"점진적 말 산출·문법의 어려움","action":"충분한 시간을 주고 그림·글·예아니오 방식 중 가능한 수단을 찾는다.","followup":"의사소통 수단과 피로 정도를 기록한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-07","name":"단어찾기형 PPA와 언어 감별","track":"치매 유형·감별·맞춤 돌봄","reason":"단어찾기형(logopenic) PPA는 알츠하이머병 병리와 연관될 수 있다. 모든 PPA를 전두측두엽 치매로 동일시하지 않는다.","scenario":"단어가 떠오르지 않고 긴 문장 반복이 어려운 환자를 모두 전두측두엽 치매라고 부른다.","focus":"언어 증후군과 원인 질환의 구분","action":"언어 평가 결과를 확인하고 실제 어려움에 맞추어 짧게 설명한다.","followup":"의료진이 확인한 진단과 관찰만 분리해 기록한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-08","name":"루이소체 치매","track":"치매 유형·감별·맞춤 돌봄","reason":"루이소체 치매에서는 환시·파킨슨 증상 등이 나타날 수 있다. 일부 항정신병약에 민감할 수 있어 임의 투약을 하지 않는다.","scenario":"인지 상태가 변동하고 사람 형상의 환시를 말한다.","focus":"인지 변동·환시와 안전","action":"환자의 불안을 인정하며 위험을 제거하고 새 변화와 약물 정보를 보고한다.","followup":"처방 후 새 졸림·경직·기능 저하를 보고한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-09","name":"파킨슨병 치매","track":"치매 유형·감별·맞춤 돌봄","reason":"파킨슨병 관련 치매와 루이소체 치매의 구분은 전문 평가가 필요하다. 환각·저혈압·삼킴 등 기능별 도움을 조정한다.","scenario":"오래된 파킨슨병 환자가 계획하기와 복약 일정 이해에 어려움을 보인다.","focus":"운동장애와 인지저하의 동반","action":"운동·인지 상태에 맞추어 한 단계씩 돕고 복약 계획을 담당자와 확인한다.","followup":"도움 수준과 투약 전후 변화 관찰을 인계한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-10","name":"기타 뇌손상에 의한 인지장애","track":"치매 유형·감별·맞춤 돌봄","reason":"외상·저산소성 손상 등은 인지장애를 남길 수 있다. 모든 손상 후 상태가 진행성 치매는 아니며 경과와 재활 목표를 구분한다.","scenario":"외상성 뇌손상 뒤 주의력 저하와 쉽게 화내는 변화가 남았다.","focus":"뇌손상 후 실행기능·정서 조절","action":"자극을 줄이고 짧은 과제를 제시하며 재활팀 계획을 따른다.","followup":"과제 지속 시간과 과부하 신호를 공유한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-11","name":"정상압수두증 등 평가 가능한 원인","track":"치매 유형·감별·맞춤 돌봄","reason":"정상압수두증은 평가·치료를 고려할 수 있는 원인 중 하나다. 세 증상만으로 진단하거나 치료 후 완치를 약속하지 않는다.","scenario":"보행이 느려지고 배뇨 문제와 인지저하가 함께 생겼다.","focus":"보행·배뇨·인지의 복합 변화","action":"증상 발생 순서와 변화를 진료팀에 전달한다.","followup":"검사·치료 계획과 이후 기능 변화를 확인한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-12","name":"약물·비타민 결핍 관련 인지저하","track":"치매 유형·감별·맞춤 돌봄","reason":"약물 부작용이나 영양 결핍은 교정 가능한 인지저하 원인이 될 수 있다. 원인 검사는 의료진이 결정하며 치매와 동반될 수도 있다.","scenario":"새 수면제 사용 뒤 졸림이 심해지고 식사도 줄었다.","focus":"약물 변화·영양 위험과 인지 변화","action":"복용 목록과 발생 시각을 보고하고 약을 독자적으로 중단·증량하지 않는다.","followup":"의료진 조정 후 각성·섭취·낙상을 관찰한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-13","name":"전신적 질환과 인지 변화","track":"치매 유형·감별·맞춤 돌봄","reason":"간·신장·갑상선 문제나 대사 이상은 인지 증상을 일으킬 수 있다. 급성 뇌병증·섬망과 만성 치매를 구분해 평가해야 한다.","scenario":"간·신장 질환이 있는 환자가 평소보다 혼돈하고 처진다.","focus":"전신 질환 악화에 동반한 의식·인지 변화","action":"즉시 상태를 보고하고 호흡·반응·섭취 안전을 확보한다.","followup":"원인 평가와 개인별 수분·약물·식이 계획을 확인한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-14","name":"섬망과 치매의 구별","track":"치매 유형·감별·맞춤 돌봄","reason":"치매 환자에게 섬망이 겹칠 수 있다. 감염·탈수·통증·약물 등 평가가 필요하며 단순 치매 악화로 단정하지 않는다.","scenario":"기존 치매 환자가 오늘 갑자기 주의집중을 못하고 밤낮으로 상태가 변한다.","focus":"급성 발병·주의력 변화·변동성","action":"새 증상으로 신속히 보고하고 평소 상태를 전달한다.","followup":"안경·보청기와 익숙한 환경 지원 후 반응을 확인한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-15","name":"우울과 인지저하","track":"치매 유형·감별·맞춤 돌봄","reason":"우울은 인지 수행에 영향을 줄 수 있고 치매와 공존할 수도 있다. 가성치매라는 말로 평가를 끝내거나 치료로 모두 회복된다고 단정하지 않는다.","scenario":"기억이 나쁘다고 호소하며 의욕·즐거움·수면이 모두 줄었다.","focus":"우울 증상과 인지 호소의 동반","action":"비판 없이 듣고 지속 기간과 기능 변화를 진료팀에 보고한다.","followup":"기분·식사·수면과 안전 문제를 지속 관찰한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-16","name":"행동심리증상과 통증","track":"치매 유형·감별·맞춤 돌봄","reason":"행동은 의사소통일 수 있다. 강압·억제보다 원인 확인과 환경 조정이 우선이며 급격한 변화는 보고한다.","scenario":"목욕 때마다 환자가 손을 밀치며 소리친다.","focus":"거부 행동의 통증·불안·환경 원인","action":"잠시 멈추고 동의를 다시 구하며 통증·추위·수치심을 확인한다.","followup":"환자가 수용한 방법과 남은 불편을 인계한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-17","name":"배회·실종 예방과 자율성","track":"치매 유형·감별·맞춤 돌봄","reason":"무조건 가두기보다 생활 이력과 배회 시간·욕구를 이해한다. 제한 조치는 개인 판단으로 시행하지 않는다.","scenario":"저녁마다 집에 가겠다며 출입구로 향한다.","focus":"이동 욕구와 실종 위험의 균형","action":"감정을 인정하고 안전한 동행·활동과 기관의 실종 예방 계획을 따른다.","followup":"위험 시간대·효과적인 동행 방법을 공유한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-18","name":"치매의 식사·삼킴 돌봄","track":"치매 유형·감별·맞춤 돌봄","reason":"치매 단계에 따라 식사 기능이 달라진다. 강제 급식·임의 식이 농도 변경은 피하고 구강 상태·선호·돌봄 목표를 고려한다.","scenario":"입에 음식을 오래 머금고 식사 뒤 젖은 목소리가 난다.","focus":"삼킴 위험과 식사 기능 저하","action":"식사 보조를 중단하고 평가를 요청하며 현재 식이 지시를 확인한다.","followup":"섭취·기침·편안함과 평가 후 계획을 기록한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-19","name":"의사결정 지원과 가족 부담","track":"치매 유형·감별·맞춤 돌봄","reason":"진단명만으로 모든 의사결정 능력을 없다고 보지 않는다. 가족의 부담을 듣되 환자 선호·동의와 기관 절차를 존중한다.","scenario":"말이 느리다는 이유로 가족이 모든 선택을 대신하려 한다.","focus":"과제별 의사결정 지원과 존엄","action":"쉬운 선택지와 의사소통 시간을 제공하고 환자의 표현을 확인한다.","followup":"환자 선택과 가족 지원 요청을 구분해 기록한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"D-20","name":"진행 단계·완화돌봄·통합 인계","track":"치매 유형·감별·맞춤 돌봄","reason":"진행성 질환에서도 편안함과 존엄을 위한 돌봄은 계속된다. 치료 가능한 원인 평가는 필요하지만 회복을 보장하지 않는다.","scenario":"중증 치매 환자의 반응이 줄어 가족이 더 강한 훈련을 원한다.","focus":"기능 단계와 편안함 중심 목표 조정","action":"통증·호흡·구강·자세를 살피고 가족과 의료진의 목표 논의를 돕는다.","followup":"증상 완화 반응과 합의된 돌봄 목표를 인계한다.","source":"https://www.ninds.nih.gov/health-information/disorders/dementias"},{"id":"U01","name":"급성 변화와 평소 인지상태","reason":"치매가 있어도 급성 변화는 별도 평가가 필요하다. 간병사는 섬망을 확진하지 않고 변화의 시간 경과를 제공한다.","scenario":"평소 짧은 대화가 가능하던 환자가 오늘 갑자기 집중하지 못하고 낮에도 처진다.","focus":"평소와 다른 급성 의식·주의력 변화","action":"변화 시작 시각과 평소 상태를 즉시 간호사에게 보고한다.","followup":"의료진 평가 후 반응·섭취·각성 상태의 변화를 인계한다."},{"id":"U02","name":"통증의 비언어적 표현","reason":"거부 행동을 성격 문제로 단정하면 통증을 놓칠 수 있다. 관찰 도구 사용은 교육받은 범위에서 돕는다.","scenario":"말로 통증을 설명하기 어려운 환자가 옷을 갈아입힐 때 얼굴을 찡그리고 오른팔을 감싼다.","focus":"동작과 관련된 통증 가능성","action":"아픈 동작을 멈추고 행동·부위·발생 상황을 보고한다.","followup":"허용된 동작으로 보조한 뒤 찡그림과 방어 행동이 줄었는지 살핀다."},{"id":"U03","name":"반복 질문과 불안","reason":"논쟁보다 안심할 수 있는 관계와 예측 가능한 환경이 도움이 된다. 사실을 강요하거나 창피를 주지 않는다.","scenario":"환자가 5분마다 집에 언제 가느냐고 묻고 출입문을 바라본다.","focus":"기억장애와 함께 나타나는 불안","action":"감정을 먼저 인정하고 짧고 일관된 설명과 익숙한 단서를 제공한다.","followup":"설명 방식에 따른 불안 정도와 환자가 선호한 표현을 인계한다."},{"id":"U04","name":"배회와 개인별 안전","reason":"걷고 싶은 이유를 살피면서 낙상과 무단 이탈을 예방한다. 일률적 억제는 돌봄의 대안이 아니다.","scenario":"오후마다 복도를 걷는 환자가 오늘 비상구 쪽으로 혼자 이동한다.","focus":"이탈 위험과 이동 욕구의 동시 고려","action":"곁에서 안전한 경로로 동행하고 기관의 이탈 예방 절차를 따른다.","followup":"배회 시간·배뇨 욕구·환경 자극과 안전한 동행 방법을 기록한다."},{"id":"U05","name":"식사 실행의 어려움","reason":"인지장애가 모든 기능의 상실을 뜻하지 않는다. 과도한 대행은 잔존 기능과 자율성을 줄일 수 있다.","scenario":"숟가락을 앞에 두고도 식사를 시작하지 못하지만 한 동작씩 안내하면 스스로 먹는다.","focus":"남아 있는 기능을 활용하는 단계별 도움","action":"짧게 한 단계씩 안내하고 스스로 수행할 시간을 준다.","followup":"도움 단계와 실제 섭취량을 기록하고 새 기침이 있으면 식사를 중단해 알린다."},{"id":"U06","name":"목욕 거부와 동의","reason":"거부를 힘으로 극복하지 않는다. 온도·통증·낯선 사람·수치심이 원인일 수 있다.","scenario":"목욕 준비 때 환자가 몸을 가리고 싫다고 말한다. 급한 위생 처치가 필요한 상황은 아니다.","focus":"사생활·거부 의사·불편 원인의 확인","action":"노출을 줄이고 이유를 살피며 시간이나 방법을 바꾸어 제안한다.","followup":"받아들인 부분 세정 방법과 거부가 줄어든 조건을 돌봄팀에 전달한다."},{"id":"U07","name":"저녁 시간의 초조","reason":"반복 관찰로 유발 요인을 찾되 모든 초조를 치매 증상으로 설명하지 않는다. 새 증상은 의료진에게 알린다.","scenario":"저녁마다 소음이 커질 때 초조해지는 양상이 일지에 반복된다.","focus":"환경 자극과 행동의 시간적 연관","action":"소음과 혼잡을 줄이고 익숙한 일과를 유지한다.","followup":"개입 전후 행동의 빈도·지속 시간·환경을 비교한다."},{"id":"U08","name":"의사소통과 감각 보조","reason":"잘 듣지 못한 반응을 이해 능력 상실로 단정하지 않는다. 감각 보조와 쉬운 표현을 먼저 점검한다.","scenario":"보청기를 사용하지 않은 날 환자가 설명에 반응하지 않아 인지기능이 나빠진 것처럼 보인다.","focus":"감각장애가 의사소통에 미치는 영향","action":"보청기 사용 계획과 작동 상태를 확인하고 정면에서 천천히 말한다.","followup":"보조기 사용 후 이해·반응 변화와 필요한 도움을 기록한다."},{"id":"U09","name":"개인별 삶의 이력","reason":"활동은 획일적으로 적용하지 않는다. 과거 취향도 현재 반응과 다를 수 있다.","scenario":"환자가 낯선 음악에는 초조하지만 예전에 즐기던 노래를 들으면 편안해한다.","focus":"개인의 선호와 삶의 이력에 근거한 활동","action":"환자 반응과 동의를 살피며 익숙한 음악을 짧게 제공한다.","followup":"편안했던 곡·시간·중단 신호를 기록하여 다음 돌봄에 활용한다."},{"id":"U10","name":"가족과 돌봄 연속성","reason":"돌봄 계획은 과거 기능과 현재 기능을 구분해야 한다. 가족의 경험과 현장 관찰 모두를 확인한다.","scenario":"가족은 혼자 식사한다고 말하지만 최근 3일 일지에는 단계별 도움이 필요했다고 적혀 있다.","focus":"가족 설명과 현재 관찰의 차이","action":"가족을 비난하지 않고 구체적인 최근 수행 수준을 팀과 공유한다.","followup":"필요한 도움을 가족에게 설명한 뒤 직접 설명해 보도록 하여 이해를 확인한다."}]},{"id":"hospice","title":"호스피스·완화돌봄전문간병사","category":"특화 교육","scope":"중증 질환의 편안함·존엄·가족 지원·증상 보고·돌봄 연속성","tracks":["중증 질환의 편안함·존엄·가족 지원·증상 보고·돌봄 연속성"],"units":[{"id":"U01","name":"돌봄 목표","reason":"완화돌봄은 고통과 삶의 질을 함께 다룬다. 간병사가 치료 중단을 결정한다는 뜻이 아니다.","scenario":"환자는 가족과 이야기할 기력을 남기고 싶어 하지만 일과는 활동량 증가 위주다.","focus":"환자 가치에 맞춘 돌봄 목표","action":"환자 선호를 듣고 담당팀과 일과·휴식의 조정을 상의한다.","followup":"환자가 중요하게 여긴 목표와 합의된 계획을 인계한다."},{"id":"U02","name":"통증의 재평가","reason":"중재가 있었다고 효과를 단정하지 않는다. 진정으로 조용해진 것과 통증 완화는 다를 수 있다.","scenario":"통증 대응 뒤 환자는 조금 낫다고 하지만 여전히 잠들기 어렵다.","focus":"증상과 기능에 대한 반복 평가","action":"환자 표현·같은 척도·수면 영향을 담당자에게 전달한다.","followup":"편안함·각성·호흡 변화와 환자 목표 달성 여부를 기록한다."},{"id":"U03","name":"숨참과 곁 지키기","reason":"새 호흡 악화를 불안 탓으로만 돌리지 않는다. 환자 선호와 치료 계획을 함께 따른다.","scenario":"환자가 숨차고 무섭다며 곁에 있어 달라고 한다.","focus":"호흡 평가와 정서 지지의 병행","action":"즉시 담당자에게 알리고 편한 허용 자세와 차분한 동행을 돕는다.","followup":"도움이 된 표현·자세·증상 경과를 인계한다."},{"id":"U04","name":"입마름과 금식","reason":"물을 마시게 하는 것과 구강 관리는 다르다. 마시지 못해도 편안함을 위한 돌봄은 가능하다.","scenario":"삼킴이 어렵고 금식 중인 환자가 입이 매우 마르다고 한다.","focus":"흡인 위험을 고려한 구강 편안함","action":"허용된 구강 보습·입술 관리 방법을 간호사에게 확인해 돕는다.","followup":"관리 전후 불편과 출혈·통증을 살핀다."},{"id":"U05","name":"섭취 감소와 가족","reason":"식사 강요나 치료 결정 대행 대신 환자 뜻과 의학적 평가를 함께 확인한다.","scenario":"환자가 먹기 싫다고 하자 가족이 굶겨 죽게 하는 것이라며 걱정한다.","focus":"섭취 감소에 대한 설명·목표 공유 필요","action":"환자의 불편을 듣고 가족과 담당팀의 설명 시간을 연결한다.","followup":"환자 의사·가족 질문·팀 설명을 구분해 기록한다."},{"id":"U06","name":"급성 초조","reason":"말기라는 이유로 모든 변화를 자연스러운 과정으로 단정하지 않는다. 원인·목표에 따른 평가가 필요하다.","scenario":"환자가 갑자기 침대에서 내려가려 하고 사람을 알아보지 못한다.","focus":"섬망 등을 포함한 급성 변화","action":"안전을 확보하고 즉시 담당자에게 평소와 달라진 점을 알린다.","followup":"유발 상황·의식·각성 변동과 도움이 된 환경을 전달한다."},{"id":"U07","name":"임종 관련 설명","reason":"간병사는 관찰만으로 사망 시각을 예측하거나 확정하지 않는다. 모르는 것은 모른다고 설명한다.","scenario":"가족이 호흡 양상이 달라졌다며 남은 시간을 정확히 말해 달라고 한다.","focus":"예후 설명의 불확실성과 역할 경계","action":"변화를 의료진에게 알리고 설명을 연결하며 가족 곁에서 지지한다.","followup":"가족 질문과 의료진의 확인된 안내를 구분해 남긴다."},{"id":"U08","name":"사전 의향과 응급상황","reason":"구두 요구만으로 간병사가 응급 대응이나 치료 범위를 결정하지 않는다.","scenario":"가족이 구두로 아무 조치도 하지 말라고 하지만 확인된 계획은 인계되지 않았다.","focus":"공식 치료 계획 확인과 신속한 보고","action":"즉시 담당 의료진에게 상황과 가족 말을 알리고 기관 절차를 따른다.","followup":"확인된 지시·설명 담당자·시각을 기록한다."},{"id":"U09","name":"문화·영적 선호","reason":"간병사의 신념을 강요하지 않는다. 가능한 환경 조정과 가족 소통을 돕는다.","scenario":"환자가 조용히 기도할 시간을 원하지만 가족은 다른 의식을 권한다.","focus":"환자의 가치·선호 존중","action":"환자 뜻을 우선 확인하고 원하면 관련 지원 인력을 연결한다.","followup":"환자가 동의한 의식·방문·환경을 인계한다."},{"id":"U10","name":"간병사의 소진","reason":"소진은 환자 안전에도 영향을 준다. 혼자 감당하거나 환자에게 감정을 떠넘기지 않는다.","scenario":"지속적인 임종 돌봄 뒤 간병사가 잠을 못 자고 집중이 어렵다.","focus":"돌봄 제공자의 안전과 지원 필요","action":"관리자에게 상태를 알리고 교대·휴식·상담 지원을 요청한다.","followup":"안전한 인계와 휴식 계획을 확인한다."}]},{"id":"pressure","title":"욕창전문간병사","category":"돌봄 특화","scope":"압박손상 심화 학습자료","tracks":["압박손상 심화"],"units":[]}];

